def season_focus(now):
    """What US students are dealing with right now (used to pick timely topics). No exact exam dates on purpose."""
    m = now.month
    if m in (8, 9):
        return "back to school: foundations, first units, study habits, early SAT/ACT prep"
    if m in (10, 11, 12):
        return "fall semester units and midterms/finals, SAT and ACT fall test dates, college application season"
    if m in (1, 2):
        return "second semester starts, new units, AP course pacing, SAT/ACT spring prep"
    if m in (3, 4):
        return "AP exam crunch: review of the whole course, practice FRQs and multiple choice, SAT/ACT spring tests"
    if m == 5:
        return "AP exams and final exams: last-minute review, high-yield topics, test-day strategy"
    return "summer: SAT/ACT prep, getting ahead for next year, review of weak topics"


