def _parse_json(txt):
    txt = txt.strip()
    txt = re.sub(r"^```(?:json)?|```$", "", txt, flags=re.M).strip()
    a, b = txt.find("{"), txt.rfind("}")
    if a < 0 or b < 0:
        raise ValueError("no json")
    return json.loads(txt[a:b + 1])


_MODELS = None


def gemini_models(key):
    """Ask Google which Gemini models this key can use (model names change over time), best free-tier candidates first."""
    global _MODELS
    if _MODELS is not None:
        return _MODELS
    names = [os.getenv("GEMINI_MODEL")] if os.getenv("GEMINI_MODEL") else []
    try:
        r = requests.get("https://generativelanguage.googleapis.com/v1beta/models", headers={"x-goog-api-key": key},
                         params={"pageSize": 200}, timeout=30)
        r.raise_for_status()
        found = []
        for m in r.json().get("models", []):
            n = m.get("name", "").replace("models/", "")
            if not n.startswith("gemini") or "generateContent" not in m.get("supportedGenerationMethods", []):
                continue
            if any(x in n for x in ("image", "tts", "embed", "live", "audio", "robotics", "computer", "learnlm", "customtools")):
                continue
            found.append(n)

        def rank(n):
            v = re.search(r"gemini-(\d+(?:\.\d+)?)", n)
            ver = float(v.group(1)) if v else 0.0
            lite_first = os.getenv("GEMINI_PREFER_LITE", "1") != "0"   # lite models have far higher free-tier request limits
            tier = (0 if "lite" in n else 1) if (lite_first and "flash" in n) else (0 if ("flash" in n and "lite" not in n) else (1 if "flash" in n else 2))
            unstable = 1 if ("preview" in n or "exp" in n) else 0
            return (tier, unstable, -ver, n)

        names += sorted(found, key=rank)[:6]
    except Exception as e:
        log("  could not list Gemini models:", e)
    names += ["gemini-flash-latest", "gemini-flash-lite-latest"]
    _MODELS = list(dict.fromkeys(names))
    log("  Gemini models to try:", _MODELS[:6])
    return _MODELS


def _gemini(prompt, system, temp):
    key = os.getenv("GEMINI_API_KEY")
    if not key:
        raise RuntimeError("GEMINI_API_KEY missing")
    last = None
    for model in gemini_models(key):
        url = f"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent"
        body = {"contents": [{"role": "user", "parts": [{"text": prompt}]}],
                "systemInstruction": {"parts": [{"text": system}]},
                "generationConfig": {"temperature": temp, "responseMimeType": "application/json"}}
        for attempt in range(3):
            try:
                r = requests.post(url, headers={"x-goog-api-key": key}, json=body, timeout=240)
            except Exception as e:
                last = e
                time.sleep(5)
                continue
            if r.status_code == 200:
                try:
                    return r.json()["candidates"][0]["content"]["parts"][0]["text"]
                except Exception as e:
                    last = e
                    break
            last = f"{model} HTTP {r.status_code}: {r.text[:160]}"
            if r.status_code == 429 and re.search(r"PerDay|per day|daily", r.text, re.I):
                log(f"   {model}: daily free quota used up, trying next model")
                break
            if r.status_code in (429, 500, 502, 503):
                time.sleep(15 * (attempt + 1))
                continue
            break
    raise RuntimeError(f"gemini failed: {last}")


def _openai(prompt, system, temp, model=None):
    key = os.getenv("OPENAI_API_KEY")
    if not key:
        raise RuntimeError("OPENAI_API_KEY missing")
    r = requests.post("https://api.openai.com/v1/chat/completions",
                      headers={"Authorization": f"Bearer {key}"},
                      json={"model": model or OPENAI_MODEL, "temperature": temp,
                            "response_format": {"type": "json_object"},
                            "messages": [{"role": "system", "content": system}, {"role": "user", "content": prompt}]},
                      timeout=240)
    r.raise_for_status()
    return r.json()["choices"][0]["message"]["content"]


def _groq(prompt, system, temp, model=None):
    """Third free fallback (console.groq.com, free key, OpenAI-compatible). Set GROQ_API_KEY; model via GROQ_MODEL."""
    key = os.getenv("GROQ_API_KEY")
    if not key:
        raise RuntimeError("GROQ_API_KEY missing")
    r = requests.post("https://api.groq.com/openai/v1/chat/completions", headers={"Authorization": f"Bearer {key}"},
                      json={"model": model or os.getenv("GROQ_MODEL", "llama-3.3-70b-versatile"), "temperature": temp,
                            "response_format": {"type": "json_object"},
                            "messages": [{"role": "system", "content": system}, {"role": "user", "content": prompt}]}, timeout=240)
    r.raise_for_status()
    return r.json()["choices"][0]["message"]["content"]


_LAST_LLM = [0.0]
LLM_GAP = float(os.getenv("LLM_GAP", "5"))   # seconds between calls: keeps us under the free per-minute limits


def llm_json(prompt, system=SYSTEM, temp=0.9, order=None):
    """order=("openai","gemini") puts ChatGPT first (used for independent checking so a different model reviews the work)."""
    errs = []
    fns = {"gemini": _gemini, "openai": _openai, "groq": _groq}
    order = list(order or ("gemini", "openai")) + [o for o in ("gemini", "openai", "groq") if o not in (order or ("gemini", "openai"))]
    for fn in [fns[o] for o in order]:
        if fn is _groq and not os.getenv("GROQ_API_KEY"):
            continue
        if fn is _openai and not os.getenv("OPENAI_API_KEY"):
            continue
        if fn is _gemini and not os.getenv("GEMINI_API_KEY"):
            continue
        for _ in range(2):
            try:
                time.sleep(max(0.0, LLM_GAP - (time.time() - _LAST_LLM[0])))
                _LAST_LLM[0] = time.time()
                out = _parse_json(fn(prompt, system, temp))
                time.sleep(2)
                return out
            except Exception as e:
                errs.append(f"{fn.__name__}: {e}")
                time.sleep(3)
    raise RuntimeError("LLM failed: " + " | ".join(errs[-3:]))



# ============================================================ MATH VERIFICATION (sympy + independent solvers)
try:
    import sympy as sy
    from sympy.parsing.sympy_parser import parse_expr, standard_transformations, implicit_multiplication_application, convert_xor
    _TR = standard_transformations + (implicit_multiplication_application, convert_xor)
    HAVE_SYMPY = True
except Exception:
    HAVE_SYMPY = False

_ALLOWED = {"x", "y", "z", "t", "a", "b", "c", "d", "k", "h", "m", "n", "r", "p", "q", "s", "u", "v", "w", "pi", "e", "E", "sqrt",
            "sin", "cos", "tan", "log", "ln", "exp", "abs", "Abs", "asin", "acos", "atan", "Rational"}


class _Timeout(Exception):
    pass


def _with_timeout(sec, fn, *a):
    """sympy can hang on odd input: give every call a few seconds (Linux/GitHub Actions)."""
    try:
        import signal

        def h(*_):
            raise _Timeout()
        old = signal.signal(signal.SIGALRM, h)
        signal.alarm(sec)
        try:
            return fn(*a)
        finally:
            signal.alarm(0)
            signal.signal(signal.SIGALRM, old)
    except (ImportError, AttributeError, ValueError):
        return fn(*a)


def disp_to_py(t):
    t = str(t)
    for a, b in (("−", "-"), ("–", "-"), ("×", "*"), ("·", "*"), ("÷", "/"), ("π", "pi"), ("²", "**2"), ("³", "**3"), ("⁴", "**4")):
        t = t.replace(a, b)
    t = re.sub(r"√\s*\(([^()]*)\)", r"sqrt(\1)", t)
    t = re.sub(r"√\s*([0-9]+|[a-zA-Z])", r"sqrt(\1)", t)
    return re.sub(r"(\d)(sqrt)", r"\1*\2", t)


def to_sym(s):
    s = str(s).strip().replace("^", "**")
    if not s or len(s) > 200 or "__" in s or re.search(r"[^0-9A-Za-z_+\-*/().,\s]", s):
        raise ValueError("bad chars")
    for nm in re.findall(r"[A-Za-z_][A-Za-z_0-9]*", s):
        if nm not in _ALLOWED:
            raise ValueError("bad name " + nm)
    return parse_expr(s, transformations=_TR, evaluate=True, local_dict={"ln": sy.log, "abs": sy.Abs})


def eq_expr(s):
    if str(s).count("=") != 1 or re.search(r"[<>]", str(s)):
        raise ValueError("not an equation")
    l, r = str(s).split("=")
    return to_sym(l) - to_sym(r)


def _sets_equal(sa, sb):
    if len(sa) != len(sb):
        return False
    return all(any(sy.simplify(x - y) == 0 for y in sb) for x in sa)


def eq_equiv(a, b):
    """True / False / None(unknown) for two equations written 'lhs = rhs' (same solution set)."""
    if not HAVE_SYMPY:
        return None

    def go():
        ea, eb = sy.expand(eq_expr(a)), sy.expand(eq_expr(b))
        if ea == 0 and eb == 0:
            return True
        if ea == 0 or eb == 0:
            return False
        ratio = sy.cancel(sy.together(ea / eb))
        if ratio.is_number and ratio != 0:
            return True
        free = ea.free_symbols | eb.free_symbols
        if len(free) == 1:
            v = next(iter(free))
            return _sets_equal(sy.solve(ea, v), sy.solve(eb, v))
        return False
    try:
        return _with_timeout(8, go)
    except Exception:
        return None


def disp_matches_py(disp, py):
    """The equation shown on screen must equal the verified one. True / False / None."""
    if not HAVE_SYMPY or not disp or not py:
        return None

    def go():
        d = sy.expand(eq_expr(disp_to_py(disp)) - eq_expr(py))
        if d == 0:
            return True
        ea, eb = sy.expand(eq_expr(disp_to_py(disp))), sy.expand(eq_expr(py))
        r = sy.cancel(sy.together(ea / eb)) if eb != 0 else None
        return bool(r is not None and r.is_number and r == 1)
    try:
        return _with_timeout(8, go)
    except Exception:
        return None


def val_equal(x, y):
    try:
        if HAVE_SYMPY:
            a, b = to_sym(x), to_sym(y)
            d = _with_timeout(8, lambda: sy.simplify(a - b))
            if d == 0 or abs(float(sy.N(d))) < 1e-6:
                return True
            # rounded decimals (e.g. molar mass 74.1 vs 74.093): allow 0.1% only when a value is a decimal, never for exact integers/fractions
            if (a.has(sy.Float) or b.has(sy.Float)) and a.is_number and b.is_number:
                fa, fb = float(sy.N(a)), float(sy.N(b))
                return abs(fa - fb) <= 0.001 * max(abs(fa), abs(fb), 1e-9)
            return False
    except Exception:
        pass
    nx, ny = re.sub(r"[\s*]", "", str(x)).lower(), re.sub(r"[\s*]", "", str(y)).lower()
    return nx == ny if nx and ny else None


def answers_match(a, b):
    if not a or not b or not isinstance(b, list) or len(a) != len(b):
        return None
    res = [val_equal(x, y) for x, y in zip(a, b)]
    if any(r is False for r in res):
        return False
    return True if all(r for r in res) else None


def circle_ok(g, start_py):
    """The graphed circle must really satisfy the original equation (4 points on it)."""
    if not HAVE_SYMPY or not start_py:
        return None
    try:
        h, k, r = (sy.nsimplify(float(g[q])) for q in ("h", "k", "r"))
        e = eq_expr(start_py)
        X, Y = sy.Symbol("x"), sy.Symbol("y")
        return all(sy.simplify(e.subs({X: px, Y: py})) == 0 for px, py in ((h + r, k), (h - r, k), (h, k + r), (h, k - r)))
    except Exception:
        return None


SOLVER_SYS = ("You are a meticulous US high school teacher. Solve exactly what is asked, recompute every calculation twice, never guess. "
              "Output valid JSON only.")


def solve_vote(p, order):
    labels = p.get("labels") or []
    ch = ("\nCHOICES:\n" + "\n".join(p["choices"])) if p.get("choices") else ""
    prompt = (f"Solve this problem completely from scratch.\nPROBLEM: {p.get('task', '')} {p.get('statement_eq') or p['statement']}{ch}\n"
              'Return JSON: {"work": [short lines], "answers": [ONE python/sympy-parsable ASCII value per label, in order, labels: '
              f'{json.dumps(labels)}; use ** for powers, sqrt(), pi; or [] if not numeric], "letter": "A"|"B"|"C"|"D"|null, "final": "short answer"}}')
    try:
        return llm_json(prompt, system=SOLVER_SYS, temp=0.0, order=order)
    except Exception as e:
        log("   solver vote unavailable:", e)
        return None


def judge_same(p, j):
    """Fallback for non-numeric answers: ask a judge whether two answers agree."""
    try:
        r = llm_json(f'Problem: {p["statement"]}\nAnswer A: {p["answer_text"]}\nAnswer B: {j.get("final")}\n'
                     'Do A and B give the same final result (ignore wording)? JSON: {"same": true|false}', system=SOLVER_SYS, temp=0.0)
        return bool(r.get("same"))
    except Exception:
        return None


def verify_problem(p):
    """Returns (ok, reasons). A problem is only used if its steps, its answer and independent solvers all agree."""
    why = []
    st = p["steps"]
    if len(st) < 2:
        why.append("needs at least 2 steps")
    chain = ([p["start_py"]] if p.get("start_py") else []) + [s["py"] for s in st if s.get("py")]
    pairs = 0
    for a, b in zip(chain, chain[1:]):
        r = eq_equiv(a, b)
        pairs += 1 if r else 0
        if r is False:
            why.append(f"step is NOT equivalent to the previous equation: '{a}'  ->  '{b}'")
    if len(chain) >= 2 and eq_equiv(chain[0], chain[-1]) is False:
        why.append("the last equation is not equivalent to the starting equation")
    for s in st:  # what is shown on screen must be what was verified
        if disp_matches_py(s.get("eq"), s.get("py")) is False:
            why.append(f"on-screen equation '{s['eq']}' differs from its verified form '{s['py']}'")
    if disp_matches_py(p.get("statement_eq"), p.get("start_py")) is False:
        why.append("the equation shown in the problem differs from start_py")
    g = p.get("graph")
    if g and g.get("type") == "circle":
        c = circle_ok(g, p.get("start_py"))
        if c is False:
            log("   graph spec does not match the equation: graph dropped")
            p["graph"] = None
    if p.get("choices"):
        cp = p.get("choices_py") or []
        if len(p["choices"]) != 4 or p.get("correct") not in "ABCD" or not p.get("correct"):
            why.append("exam question needs exactly 4 choices and a correct letter")
        elif len(cp) == 4 and HAVE_SYMPY:
            vals = [val_equal(cp[i], cp[(i + 1) % 4]) for i in range(4)]
            if any(v is True for v in vals):
                why.append("two answer choices have the same value")
            ci = "ABCD".index(p["correct"])
            if p.get("answer_py") and val_equal(cp[ci], p["answer_py"][0]) is False:
                why.append("the marked correct choice does not equal the solution value")
    if why:
        return False, why
    # independent solvers (OpenAI first, Gemini second) must reach the same answer
    votes = []
    for order in (("openai", "gemini"), ("gemini", "openai")):
        j = solve_vote(p, order)
        if not j:
            continue
        m = answers_match(p.get("answer_py"), j.get("answers"))
        if p.get("choices") and j.get("letter"):
            m = (str(j["letter"]).upper()[:1] == p["correct"]) if m in (None, True) else m
        if m is None and not p.get("answer_py") and not p.get("choices"):
            m = judge_same(p, j)
        votes.append(m)
    yes, no = votes.count(True), votes.count(False)
    log(f"   verify: steps checked={pairs}, solver votes={votes}")
    if no == 0 and yes >= 1:
        return True, []
    if yes >= 2:
        return True, []
    if not votes or (yes == 0 and no == 0):
        if pairs >= 2 and HAVE_SYMPY:
            return True, []
        return False, ["could not verify the answer independently"]
    return False, ["independent solver(s) got a different answer: " + json.dumps([v for v in votes])]


# ============================================================ DEMAND RESEARCH (Google Trends, autocomplete, top results)
UA = {"User-Agent": "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 Chrome/124 Safari/537.36"}
EDU_RE = re.compile(r"\b(sat|act|psat|ap|exam|test|school|college|math|algebra|calculus|chemistry|biology|physics|essay|homework|study|"
                    r"student|teacher|history|government|economics|gpa|scholarship|fafsa|college board|finals|midterm)\b", re.I)


def suggest(q, yt=True):
    """Autocomplete = what people really type, most popular first."""
    try:
        p = {"client": "firefox", "q": q, "hl": "en", "gl": "us"}
        if yt:
            p["ds"] = "yt"
        r = requests.get("https://suggestqueries.google.com/complete/search", params=p, headers=UA, timeout=15)
        return [str(x) for x in json.loads(r.content.decode("utf-8", "ignore"))[1]][:10]
    except Exception:
        return []


def google_trends_us():
    for url in ("https://trends.google.com/trending/rss?geo=US", "https://trends.google.com/trends/trendingsearches/daily/rss?geo=US"):
        try:
            r = requests.get(url, headers=UA, timeout=20)
            r.raise_for_status()
            import html as _h
            titles = [_h.unescape(re.sub(r"<!\[CDATA\[|\]\]>", "", t)).strip() for t in re.findall(r"<title>(.*?)</title>", r.text, re.S)[1:]]
            news = [_h.unescape(re.sub(r"<!\[CDATA\[|\]\]>", "", t)).strip() for t in re.findall(r"<ht:news_item_title>(.*?)</ht:news_item_title>", r.text, re.S)]
            out = [t for t in titles + news if EDU_RE.search(t)]
            if titles or out:
                return list(dict.fromkeys(out))[:12]
        except Exception:
            continue
    return []


def pytrends_rank(cands):
    """Optional: relative US search interest of candidate topics over the last 3 months (pip install pytrends)."""
    try:
        from pytrends.request import TrendReq
        tr = TrendReq(hl="en-US", tz=-300, timeout=(10, 20))
        out = {}
        for i in range(0, len(cands), 5):
            grp = cands[i:i + 5]
            tr.build_payload(grp, timeframe="today 3-m", geo="US")
            df = tr.interest_over_time()
            for c in grp:
                if c in df:
                    out[c] = int(df[c].tail(8).mean())
            time.sleep(2)
        return out
    except Exception:
        return {}


def yt_top_titles(q):
    """Titles currently ranking for the query: used to make ours different and better. Never fatal."""
    try:
        r = requests.get("https://www.googleapis.com/youtube/v3/search", headers={"Authorization": f"Bearer {yt_token()}"}, timeout=30,
                         params={"part": "snippet", "q": q, "type": "video", "maxResults": 8, "regionCode": "US", "relevanceLanguage": "en"}).json()
        return [it["snippet"]["title"] for it in r.get("items", [])]
    except Exception:
        return []


def research_demand(seeds, now, with_rank=False):
    res = {"season": season_focus(now), "exam_year": exam_year(now), "trends": google_trends_us(), "suggest": {}}
    for q in seeds[:6]:
        s = suggest(q) + suggest(q, yt=False)
        res["suggest"][q] = list(dict.fromkeys(s))[:10]
        time.sleep(0.4)
    if with_rank and flag("USE_PYTRENDS"):
        res["interest"] = pytrends_rank(seeds[:5])
    log("  research: trends", len(res["trends"]), "| suggestions", sum(len(v) for v in res["suggest"].values()))
    return res


def demand_text(res):
    return (f"Season now: {res['season']}. Exam year for titles: {res['exam_year']}.\n"
            f"Google Trends (US, education-related, may be empty): {json.dumps(res['trends'], ensure_ascii=False)}\n"
            f"What students type in YouTube/Google search (autocomplete, most popular first): {json.dumps(res['suggest'], ensure_ascii=False)}\n"
            + (f"Relative search interest (0-100): {json.dumps(res['interest'])}\n" if res.get("interest") else ""))


# ============================================================ SCRIPT GENERATION
ITEM_KINDS = {"bullet", "step", "eq", "q", "choice", "ans", "note", "big"}
ITEM_DOC = (
    'items: array of {"k": kind, "t": text, "n": optional small note}. Kinds: bullet (short on-screen point), '
    "step (numbered step), eq (ONE equation line in t, explain it in n), q (exam question text), "
    "choice (answer choice like 'A) 12'), ans (the answer + 1-line reason), note (small tip), big (one large statement). "
    "On-screen text must be short (max 70 chars). Items appear one by one while the hosts talk, so item order must follow the dialogue."
)


def cut(t, n):
    """Shorten at a word boundary (never mid-word like 'double membran')."""
    t = str(t).strip()
    if len(t) <= n:
        return t
    c = t[:n].rsplit(" ", 1)[0].rstrip(",;:-")
    return (c if len(c) >= n // 2 else t[:n]).rstrip() + "…"


def strip_latex(t):
    t = re.sub(r"\\begin\{cases\}(.*?)\\end\{cases\}", lambda m_: m_.group(1).replace("\\\\", "; "), t, flags=re.S)
    t = re.sub(r"\\(?:text|mathrm|textbf|mathbf)\{([^{}]*)\}", r"\1", t)
    t = re.sub(r"\\frac\{([^{}]*)\}\{([^{}]*)\}", r"(\1)/(\2)", t)
    t = re.sub(r"\\sqrt\{([^{}]*)\}", r"√(\1)", t)
    for a, b in (("\\cdot", "·"), ("\\times", "×"), ("\\pi", "π"), ("\\left", ""), ("\\right", ""), ("\\,", " "), ("\\\\", "; "), ("$", "")):
        t = t.replace(a, b)
    return re.sub(r"[\\{}]", "", t)


def clean_glyphs(t):
    t = strip_latex(str(t))
    for a in ("✓", "✔", "✗", "✘", "☑", "✅", "❌"):
        t = t.replace(a, "")
    return re.sub(r"\s+", " ", t).strip()


def norm_items(items, maxn):
    out = []
    for it in items or []:
        if isinstance(it, str):
            it = {"k": "bullet", "t": it}
        if not isinstance(it, dict):
            continue
        t = clean_glyphs(str(it.get("t", "")))
        if not t:
            continue
        k = it.get("k", "bullet")
        k = k if k in ITEM_KINDS else "bullet"
        if k in ("eq", "ans", "big"):   # 50^2 -> 50², 3 * 4 -> 3 × 4 on screen
            t = re.sub(r"\^\s*2(?!\d)", "²", t)
            t = re.sub(r"\^\s*3(?!\d)", "³", t)
            t = re.sub(r"(?<=[\d)\w]) \* (?=[\d(\w])", " × ", t)
        out.append({"k": k, "t": t if k == "eq" and len(t) <= 140 else cut(t, 230 if k == "q" else 140),
                    "n": cut(clean_glyphs(str(it.get("n", "") or "")), 100)})
    return out[:maxn]


def norm_dialogue(dl):
    out = []
    for i, x in enumerate(dl or []):
        if isinstance(x, dict):
            s, t = str(x.get("s", "")).upper()[:1], str(x.get("t", "")).strip()
        else:
            s, t = "", str(x).strip()
        if not t:
            continue
        if s not in ("A", "S"):
            s = "A" if i % 2 == 0 else "S"
        out.append({"s": s, "t": t})
    return out


def norm_scene(raw, kind, heading, short=False):
    sc = {"kind": kind, "heading": cut(str(raw.get("heading") or heading), 60),
          "items": norm_items(raw.get("items"), 3 if short else 8),
          "dialogue": norm_dialogue(raw.get("dialogue")), "graph": raw.get("graph") if isinstance(raw.get("graph"), dict) else None,
          "summary": str(raw.get("summary", ""))[:200]}
    sc["type"] = "hook" if kind in ("hook", "outro") else ("graph" if sc["graph"] else "list")
    if not sc["dialogue"]:
        raise ValueError("scene without dialogue")
    return sc


_NUM = re.compile(r"(?<![\w.])\d+(?:\.\d+)?")


def bad_numbers(dialogue, allowed_text):
    """Every number the hosts SAY must be on screen / in the verified solution (stops spoken-vs-shown mismatches)."""
    allowed = set(_NUM.findall(allowed_text.replace(",", "")))
    bad = []
    for ln in dialogue:
        for n in _NUM.findall(ln["t"].replace(",", "")):
            if n not in allowed and n not in ("0", "1", "2", "3"):
                bad.append(n)
    return sorted(set(bad))


# ---- verified problems
def _norm_problem(raw, role):
    if len(clean_glyphs(str(raw.get("statement") or ""))) > 170:
        raise ValueError("statement longer than 150 characters: rewrite it shorter (one sentence)")
    p = {"role": role, "label": cut(clean_glyphs(str(raw.get("label") or "")), 28),
         "statement": clean_glyphs(str(raw.get("statement") or "")), "task": cut(clean_glyphs(str(raw.get("task") or "")), 70),
         "statement_eq": clean_glyphs(str(raw.get("statement_eq") or ""))[:80] or None,
         "start_py": (str(raw.get("start_py")).strip() if raw.get("start_py") else None),
         "answer_text": cut(clean_glyphs(str(raw.get("answer_text") or "")), 120), "labels": [str(x) for x in (raw.get("labels") or [])][:6],
         "answer_py": [str(x) for x in (raw.get("answer_py") or [])][:6], "why": clean_glyphs(str(raw.get("why") or ""))[:110]}
    p["steps"] = []
    for s in (raw.get("steps") or [])[:6]:
        if isinstance(s, dict) and s.get("say"):
            p["steps"].append({"say": cut(clean_glyphs(str(s["say"])), 60), "eq": cut(clean_glyphs(str(s.get("eq") or "")), 90),
                               "py": (str(s["py"]).strip() if s.get("py") else None), "note": cut(clean_glyphs(str(s.get("note") or "")), 50)})
    g = raw.get("graph")
    p["graph"] = g if isinstance(g, dict) and (g.get("type") == "circle" or g.get("expr")) else None
    if role == "exam":
        ch = [re.sub(r"^[A-D]\s*[\).:]\s*", "", clean_glyphs(str(c))) for c in (raw.get("choices") or [])][:4]
        p["choices"] = [f"{'ABCD'[i]}) {c}" for i, c in enumerate(ch)]
        p["choices_py"] = [str(c) for c in (raw.get("choices_py") or [])][:4]
        p["correct"] = str(raw.get("correct") or "").strip().upper()[:1]
    if not p["statement"] or not p["answer_text"]:
        raise ValueError("problem without statement/answer")
    return p


ROLE_DOC = {
    "worked1": "WORKED EXAMPLE 1: a clean textbook problem with nice numbers that shows the core method.",
    "worked2": "WORKED EXAMPLE 2: a harder variant of the same skill (e.g. a leading coefficient, negatives, fractions). Different numbers from example 1.",
    "practice": "PRACTICE PROBLEM for the viewer: same skill, medium difficulty, solvable in about 10 seconds of thinking plus short work.",
    "exam": "EXAM QUESTION: SAT/ACT/AP-style multiple choice with EXACTLY 4 choices, one correct; the 3 wrong choices are the typical mistakes students make.",
    "short": "ONE short problem for a 40-second video: 2-4 steps, very clean numbers.",
}


def make_problem(role, area, course, unit, taken, now):
    last = ""
    for attempt in range(4):
        prompt = (
            f"Create ONE {role} problem for a US high school video.\nCourse: {course}. Topic: {unit}. Subject area: {area}.\n{ROLE_DOC[role]}\n"
            f"Problems already used (yours must be different): {json.dumps(taken, ensure_ascii=False)}\n{last}"
            'Return JSON: {"label": str (max 26 chars, complete words, e.g. "Grouping and halving"), "statement": str (the full question in words, ONE sentence, max 150 characters, it is shown on screen so it must be short), '
            '"task": str (short instruction, e.g. "Find the center and radius"), "statement_eq": str|null (ONLY the given equation, unicode math allowed), '
            '"start_py": str|null (that same equation as python/sympy text "lhs = rhs", ** for powers, * for every multiplication), '
            '"steps": [2-6 objects {"say": imperative sentence max 55 chars, "eq": result after this step (unicode math, max 60 chars) or "", '
            '"py": the same result as python/sympy "lhs = rhs" or null, "note": what changed, max 45 chars}], '
            '"answer_text": final answer with units (max 100 chars), "labels": [names of each final value], '
            '"answer_py": [one python/sympy-parsable value per label; [] if not numeric], '
            '"graph": null | {"type":"circle","h":n,"k":n,"r":n,"label":str} | {"expr":"python expr in x","xmin":n,"xmax":n,"label":str}, '
            '"choices": [4 strings WITHOUT the letter] (exam only), "choices_py": [4 python values] (exam only, if numeric), '
            '"correct": "A"|"B"|"C"|"D" (exam only), "why": one-line reason (exam only)}\n'
            "RULES: every step must be mathematically equivalent to the previous one (same solution set); py must be exactly what eq shows; "
            "py is null for lines that are not a single equation (e.g. a list of solutions); recompute all arithmetic twice. "
            "Plain unicode text ONLY on screen fields: never LaTeX (no backslashes, no \\text, no \\begin, no $). "
            "For a system of equations put both equations in statement_eq separated by '; '. "
            "Use the exact method students are taught for this topic. For history/English/economics: steps are reasoning steps "
            "(claim, evidence, reasoning), eq holds a one-line key statement, py/start_py/answer_py are null/[].")
        try:
            raw = llm_json(prompt, system="You are a strict US high school teacher writing verified textbook problems. Output valid JSON only.", temp=0.5)
            p = _norm_problem(raw, role)
        except Exception as e:
            last = f"Previous attempt was invalid ({e}). "
            log("  problem retry:", e)
            continue
        ok, why = verify_problem(p)
        if ok:
            log(f"  problem {role} verified: {p['statement'][:60]}")
            return p
        last = "PREVIOUS ATTEMPT WAS REJECTED BECAUSE: " + "; ".join(why) + ". Fix these errors. "
        log(f"  problem {role} rejected:", why)
    raise RuntimeError(f"could not produce a verified {role} problem")


def facts_text(probs):
    out = []
    for role, p in probs.items():
        out.append(f"[{role}] {p['task']} {p.get('statement_eq') or p['statement']}  steps: " +
                   " | ".join((s['eq'] or s['say']) for s in p["steps"]) + f"  ANSWER: {p['answer_text']}")
    return "\n".join(out)


def prob_allowed(p):
    return " ".join([p["statement"], p.get("statement_eq") or "", p["answer_text"], p.get("why", "")] +
                    [f"{s['say']} {s['eq']} {s['note']}" for s in p["steps"]] + (p.get("choices") or []))


# ---- turning verified problems into on-screen items (the LLM never re-types math)
def step_chunks(p, per=3):
    return [p["steps"][i:i + per] for i in range(0, len(p["steps"]), per)]


def solution_items(p, ci, chunk, last):
    items = []
    if ci == 0:
        items.append({"k": "eq", "t": p["statement_eq"], "n": p["task"] or "Start here"} if p.get("statement_eq")
                     else {"k": "q", "t": p["statement"][:140]})
    else:
        prev = step_chunks(p)[ci - 1][-1]
        items.append({"k": "eq", "t": prev["eq"], "n": "Where we left off"} if prev["eq"] else {"k": "note", "t": prev["say"]})
    for s in chunk:
        items.append({"k": "step", "t": s["say"], "n": ""})
        if s["eq"]:
            items.append({"k": "eq", "t": s["eq"], "n": s["note"]})
    if last:
        items.append({"k": "ans", "t": p["answer_text"]})
    return norm_items(items, 8)


def question_items(p):
    if p.get("choices"):
        return norm_items([{"k": "q", "t": p["statement"]}] + [{"k": "choice", "t": c} for c in p["choices"]], 8)
    if p.get("statement_eq"):
        return norm_items([{"k": "q", "t": p["task"] or p["statement"]}, {"k": "eq", "t": p["statement_eq"]}], 8)
    return norm_items([{"k": "q", "t": p["statement"]}], 8)


def exam_answer_items(p):
    ci = "ABCD".index(p["correct"])
    items = [{"k": "step", "t": s["say"], "n": ""} for s in p["steps"][:3]]
    for it in items:
        pass
    eqs = [s for s in p["steps"][:3] if s["eq"]]
    items = []
    for s in p["steps"][:3]:
        items.append({"k": "step", "t": s["say"], "n": ""})
        if s["eq"]:
            items.append({"k": "eq", "t": s["eq"], "n": s["note"]})
    items.append({"k": "ans", "t": (p["choices"][ci] + (" — " + p["why"] if p.get("why") else ""))[:130]})
    return norm_items(items, 8)


def build_specs(area, plan, probs):
    P1, P2, P3, P4 = probs["worked1"], probs["worked2"], probs["practice"], probs["exam"]
    sp_ = []

    def add(**k):
        sp_.append(k)

    hook_items = ([{"k": "eq", "t": P1["statement_eq"], "n": P1["task"]}] if P1.get("statement_eq") else [{"k": "big", "t": cut(P1["task"] or P1["statement"], 80)}])
    add(kind="hook", heading=plan.get("hook_heading") or plan["title"][:45], goal="grab attention with the first problem, welcome the subscribers, "
        "promise what they will be able to do", words=80, prefix=hook_items, allow=prob_allowed(P1))
    add(kind="explain", heading=plan.get("explain_heading") or "The key idea", goal="explain the core idea and formula behind this topic with an analogy; "
        "no worked numbers yet", words=150)
    if area in ("humanities", "science"):
        add(kind="explain", heading="Why it matters", goal="the cause-and-effect or reasoning students must be able to explain on the exam", words=130)
    for pi_, P, nm in ((1, P1, "Example 1"), (2, P2, "Example 2")):
        ch = step_chunks(P)
        for ci, c in enumerate(ch):
            add(kind="example", heading=f"{nm}: {P['label'] or 'step by step'}" + (" (continued)" if ci else ""),
                goal=f"walk through the solved steps of {nm} exactly as shown", words=120, items=solution_items(P, ci, c, ci == len(ch) - 1),
                allow=prob_allowed(P), problem=P["role"])
        if pi_ == 1 and P.get("graph"):
            g = dict(P["graph"])
            g.setdefault("label", "Graph of the answer")
            last_eq = next((s["eq"] for s in reversed(P["steps"]) if s["eq"]), "")
            gi = ([{"k": "eq", "t": last_eq, "n": "The equation we ended with"}] if last_eq else []) + [{"k": "ans", "t": P["answer_text"]}]
            add(kind="graph", heading="See it on a graph", goal="connect the algebra to the picture", words=80, items=norm_items(gi, 4), graph=g,
                allow=prob_allowed(P), problem=P["role"])
    add(kind="mistake", heading="Two mistakes to avoid", goal="the 2 most common student mistakes for THIS topic, tied to Example 1 or 2. Each item: the bullet text = the wrong idea (max 45 chars), "
        "its note n = the correct idea (max 70 chars, must agree with the verified solution)", words=110)
    add(kind="practice", heading="Your turn: try it!", goal="challenge the viewer to pause and solve it; do NOT reveal the answer", words=55,
        items=question_items(P3), think=10, allow=prob_allowed(P3), tag="YOUR TURN", problem=P3["role"])
    ch = step_chunks(P3)
    for ci, c in enumerate(ch):
        add(kind="solution", heading="Check your answer" + (" (continued)" if ci else ""), goal="reveal and explain the solution to the practice problem step by step",
            words=110, items=solution_items(P3, ci, c, ci == len(ch) - 1), allow=prob_allowed(P3), tag="SOLUTION", problem=P3["role"])
    add(kind="exam", heading="Exam-style question", goal="read the exam question, ask the viewer to pick before the answer", words=55,
        items=question_items(P4), think=7, allow=prob_allowed(P4), problem=P4["role"])
    add(kind="solution", heading="The answer and why", goal="reveal the correct choice and explain why each wrong choice is a trap", words=110,
        items=exam_answer_items(P4), allow=prob_allowed(P4), tag="ANSWER & WHY", problem=P4["role"])
    add(kind="recap", heading="Quick recap", goal="recap the method in 3-4 points; tell viewers the practice answers are in the description", words=90)
    add(kind="outro", heading="Thanks for watching!", goal="warm goodbye: thank them, ask them to subscribe and turn on the bell, to comment the topic or "
        "exam question they want next, and to watch the next lesson on screen", words=40, tag="",
        items=norm_items([{"k": "bullet", "t": "**Subscribe** for a new lesson every day"}, {"k": "bullet", "t": "**Comment** the topic you want next"},
                          {"k": "bullet", "t": "Watch the **next lesson** below"}], 3))
    return sp_


def gen_scene(plan, i, spec, outline, prev_summary, opener, n_total, facts, feedback=""):
    kind, fixed, prefix = spec["kind"], spec.get("items"), spec.get("prefix") or []
    words = int(int(spec.get("words") or 120) * 1.35)
    n_items = len(fixed) if fixed is not None else len(prefix) + 3
    nl = max(n_items + 1, 3, round(words / 20))
    extra = ""
    if i == 0:
        extra = (f"This is the opening: {opener}. Hook the viewer in the first 2 lines. Then ALEX warmly welcomes the Highlit family: "
                 "'Welcome back to Highlit' to the subscribers, 'welcome' to anyone new, plus ONE quick line asking new viewers to subscribe. "
                 "Then say what they will be able to do by the end. ")
    if i == n_total - 1:
        extra += ("Final scene (end page, about 12 seconds): ALEX thanks the viewers, SAM asks them to subscribe and turn on the bell, "
                  "ALEX asks them to comment the topic or exam question they want next and to watch the next lesson on screen. ")
    head = (f'Write scene {i + 1} of {n_total} of the video "{plan["title"]}".\nOutline: {json.dumps(outline)}\n'
            f"Previous scene summary: {prev_summary or 'none (this is the start)'}\n"
            f"THIS scene: kind={kind}, heading={spec['heading']}, goal={spec['goal']}. About {words} words, at least {nl} lines alternating naturally "
            f"between A and S. {extra}\nVERIFIED FACTS (the ONLY problems, numbers and solutions you may use):\n{facts}\n"
            "In dialogue write numbers as digits (36, −4) and operations as words (x squared, minus, divided by). Never say a number that is not in the "
            "verified facts or on screen. If SAM guesses wrong, ALEX must correct it clearly. "
            + (f"FIX THESE PROBLEMS FROM THE LAST ATTEMPT: {feedback}\n" if feedback else ""))
    if fixed is not None:
        numbered = "\n".join(f"{k + 1}. [{it['k']}] {it['t']}" + (f"  (note: {it['n']})" if it["n"] else "") for k, it in enumerate(fixed))
        prompt = (head + "ON-SCREEN ITEMS, final and verified, in the order they appear (do NOT change them):\n" + numbered +
                  "\nWrite ONLY the dialogue. Walk through the items in order, one or more lines per item, saying each number exactly as shown. "
                  + ("The scene ends with the viewer being told to pause the video and try it; do NOT reveal the answer. " if spec.get("think") else "") +
                  'Return JSON: {"dialogue": [{"s": "A"|"S", "t": str}], "summary": one sentence}')
    else:
        pre = ("The first on-screen items are already fixed: " + json.dumps(prefix, ensure_ascii=False) + ". Then add 2-3 more items. ") if prefix else "Use 3-6 items. "
        prompt = (head + ITEM_DOC + "\n" + pre + 'Return JSON: {"items": [...], "dialogue": [{"s": "A"|"S", "t": str}], "summary": one sentence}')
    last = None
    for _ in range(3):
        try:
            raw = llm_json(prompt)
            if fixed is not None:
                raw["items"] = fixed
            else:
                raw["items"] = norm_items(prefix + norm_items(raw.get("items"), 8), 8) if prefix else raw.get("items")
            raw["graph"] = spec.get("graph")
            sc = norm_scene(raw, kind, spec["heading"])
            allowed = " ".join(f"{x['t']} {x['n']}" for x in sc["items"]) + " " + (spec.get("allow") or facts)
            bad = bad_numbers(sc["dialogue"], allowed)
            if bad:
                prompt += f"\nYOUR LAST DIALOGUE SAID NUMBERS THAT ARE NOT IN THE VERIFIED FACTS/ITEMS: {bad}. Remove or correct them."
                raise ValueError(f"dialogue numbers not on screen: {bad}")
            sc["heading"] = spec["heading"]
            sc["think"] = int(spec.get("think") or 0)
            sc["tag"] = spec.get("tag", "")
            sc["problem"] = spec.get("problem", "")
            sc["allow"] = spec.get("allow") or ""
            return sc
        except Exception as e:
            last = e
            log("  scene retry:", e)
    raise RuntimeError(f"scene {i} failed: {last}")


AUDIT_SYS = ("You are a strict US high school teacher and fact-checker reviewing a video script before publication. Output valid JSON only.")


def transcript(script):
    out = []
    for i, sc in enumerate(script["scenes"]):
        out.append(f"--- SCENE {i} [{sc['kind']}] {sc['heading']}\nON SCREEN: " + " || ".join(f"{x['t']} ({x['n']})" if x["n"] else x["t"] for x in sc["items"]) +
                   (f"\nGRAPH: {json.dumps(sc['graph'])}" if sc.get("graph") else "") +
                   "\nSPOKEN: " + " / ".join(f"{d['s']}: {d['t']}" for d in sc["dialogue"]))
    return "\n".join(out)


def audit_script(script):
    """Whole-video review: math, facts, consistency between scenes, spoken vs shown. Returns list of {scene, problem}."""
    prompt = ("Review this COMPLETE video script. Recompute every calculation. Report ONLY definite errors: wrong math or facts, numbers or "
              "equations that contradict another scene, spoken words that contradict what is on screen, answer choices with no or two correct "
              "answers, a graph that does not match the equation. A line labelled as a wrong example is NOT an error. Do NOT report style, tone, theme, "
              "pacing, or whether a hook's promise matches the method. A [practice] scene (YOUR TURN) near the end is a SEPARATE new challenge on purpose "
              "(different numbers or a different question than the worked example): that is NOT an error.\n\n"
              + transcript(script) + '\n\nReturn JSON: {"errors": [{"scene": int, "type": "math"|"fact"|"mismatch", "problem": str}]}')
    errs = []
    for order in (("openai", "gemini"), ("gemini", "openai")):
        try:
            j = llm_json(prompt, system=AUDIT_SYS, temp=0.0, order=order)
            for e in j.get("errors") or []:
                if str(e.get("type", "math")).lower() not in ("math", "fact", "mismatch"):
                    continue
                try:
                    errs.append({"scene": int(e.get("scene")), "problem": str(e.get("problem"))[:300]})
                except Exception:
                    pass
        except Exception as e:
            log("  audit unavailable:", e)
    seen, out = set(), []
    for e in errs:
        k = (e["scene"], e["problem"][:40])
        if k not in seen:
            seen.add(k)
            out.append(e)
    return out


def audit_and_fix(script, specs, regen):
    """Up to 2 repair rounds: regenerate only the scenes the auditors flagged, with their feedback. Never publish with open errors."""
    for rnd in range(3):
        errs = audit_script(script)
        if not errs:
            log("  audit: clean")
            return
        log(f"  audit round {rnd + 1}: {len(errs)} issue(s):", [e["problem"][:80] for e in errs])
        if rnd == 2:
            raise RuntimeError("audit still reports errors: " + json.dumps(errs, ensure_ascii=False)[:600])
        by = {}
        for e in errs:
            if 0 <= e["scene"] < len(script["scenes"]):
                by.setdefault(e["scene"], []).append(e["problem"])
        if not by:
            raise RuntimeError("audit reported errors without a valid scene")
        for si, fb in by.items():
            script["scenes"][si] = regen(si, "; ".join(fb))


def pick_course(st, area):
    lst = SUBJECTS[area]
    return lst[st.get("course_rot", {}).get(area, 0) % len(lst)]


def next_units(st, course, n=3):
    lst = CURRICULUM.get(course, [])
    ptr = st.get("curriculum", {}).get(course, 0)
    return [lst[(ptr + j) % len(lst)] for j in range(min(n, len(lst)))]


def advance_curriculum(st, script):
    course, unit = script.get("course"), (script.get("unit") or "").lower()
    st.setdefault("course_rot", {})
    st["course_rot"][script["area"]] = st["course_rot"].get(script["area"], 0) + 1
    lst = CURRICULUM.get(course, [])
    for i, u in enumerate(lst):
        if unit and (u.lower() in unit or unit in u.lower()):
            st.setdefault("curriculum", {})[course] = (i + 1) % len(lst)
            break


def seo_pack(script, research, top_titles, st):
    """Final title/description/tags written against real search phrases and what already ranks."""
    prompt = (
        f"Video topic: {script['topic']} (course: {script.get('course')}). Draft title: {script['title']}.\n"
        f"Main search phrase students type: {script.get('search_query')}\n{demand_text(research)}"
        f"Titles that already rank for this search (do NOT copy; be clearer and more specific): {json.dumps(top_titles, ensure_ascii=False)}\n"
        f"Our recent titles (avoid repeating the pattern too much): {json.dumps(st['titles'][-12:], ensure_ascii=False)}\n"
        f"Lesson sections: {json.dumps([s['heading'] for s in script['scenes']])}\n"
        'Return JSON: {"title": str (max 66 chars; the exact search phrase or its closest natural form in the first 5 words; one honest benefit; '
        'add the exam year only if it is an SAT/ACT/AP topic), "thumb_text": str (2-4 words ALL CAPS, key word in **), '
        '"description": str (first 150 chars: main keyword + course + "step by step"; then 2 natural sentences; no hashtags), '
        '"tags": [15-20 phrases: exact search phrase first, close variants, autocomplete phrases, course and exam names], "hashtags": [3]}')
    try:
        j = llm_json(prompt, system="You are a YouTube SEO expert for education channels. Honest titles only. Output valid JSON only.", temp=0.6)
        for k in ("title", "description", "tags", "hashtags", "thumb_text"):
            if j.get(k):
                script[k] = j[k]
    except Exception as e:
        log("  seo pack skipped:", e)
    script["title"] = re.sub(r"\s+", " ", str(script["title"])).strip()[:70]


def gen_long(st, area, comments, now=None):
    now = now or datetime.now(timezone.utc)
    course = pick_course(st, area)
    cands = next_units(st, course)
    seeds = [f"{u} {course}" for u in cands] + [f"{course} help", f"{course} practice problems"]
    research = research_demand(seeds, now, with_rank=True)
    opener = random.choice(HOOK_STYLES)
    series = next((x for x in st["series"] if x["area"] == area), None)
    series_note = ""
    if series:
        series_note = (f'This video is Part {series["next"]} of {series["total"]} of the series "{series["topic"]}". '
                       f"Continue exactly where the previous part ended. Put 'Part {series['next']}' in the title. ")
    prompt = (
        "Plan ONE new long video (8-10 minutes) for US high school students that works as a reference lesson for their CURRENT school curriculum.\n"
        f"Subject area: {area}. Course this week: {course}. Next units in that course's school-year order: {json.dumps(cands)}.\n{series_note}"
        f"{demand_text(research)}"
        f"Already covered (never repeat): {json.dumps(st['titles'][-30:])}\n"
        f"Recent viewer comments (if one is a real request that fits this course, prioritize it and set from_comment true):\n{json.dumps(comments[:40], ensure_ascii=False)}\n"
        "Pick the topic with the best mix of (1) real search demand (autocomplete phrases/trends above), (2) what students in this course are studying "
        "now (the units above and the season), (3) a topic a 10-minute video can teach completely with worked examples. If it is too big, make it part 1 of up to 3.\n"
        'Return JSON: {"topic": str, "unit": str (the course unit it belongs to), "search_query": str (the exact phrase students type, taken from the '
        'suggestions when possible), "from_comment": bool, "parts_total": 1-3, "part_no": int, "title": str (max 66 chars, keyword first, honest), '
        '"hook_heading": str (max 40 chars, curiosity, about the TOPIC of the title in general, not about one example), "explain_heading": str (max 34 chars), "thumb_text": str (2-4 words ALL CAPS, key word in **), '
        '"description": str (first 150 chars packed with keywords, then a short paragraph; no hashtags), "tags": [12-18 search phrases], "hashtags": [3]}')
    plan = llm_json(prompt)
    topic = plan.get("unit") or plan.get("topic") or cands[0]
    probs, taken = {}, []
    for role in ("worked1", "worked2", "practice", "exam"):
        probs[role] = make_problem(role, area, course, f"{plan.get('topic', topic)} ({topic})", taken, now)
        taken.append(probs[role]["statement"])
    specs = build_specs(area, plan, probs)
    facts = facts_text(probs)
    outline = [{"kind": s["kind"], "heading": s["heading"]} for s in specs]
    n = len(specs)
    scenes, summary = [], ""
    for i, sp_ in enumerate(specs):
        log(f"  scene {i + 1}/{n}: {sp_['heading']}")
        sc = gen_scene(plan, i, sp_, outline, summary, opener, n, facts)
        scenes.append(sc)
        summary = sc["summary"]
    script = {"kind": "long", "area": area, "course": course, "unit": topic, "title": plan["title"], "topic": plan.get("topic", plan["title"]),
              "search_query": plan.get("search_query", ""), "description": plan.get("description", ""), "tags": plan.get("tags", []),
              "hashtags": plan.get("hashtags", []), "thumb_text": plan.get("thumb_text", "**LEARN** THIS FAST"), "scenes": scenes, "opener": opener,
              "parts_total": int(plan.get("parts_total") or 1), "part_no": int(plan.get("part_no") or 1), "series_idx": series, "problems": probs}

    def regen(si, fb):
        return gen_scene(plan, si, specs[si], outline, scenes[si - 1]["summary"] if si else "", opener, n, facts, feedback=fb)
    audit_and_fix(script, specs, regen)
    seo_pack(script, research, yt_top_titles(script.get("search_query") or script["topic"]) if os.getenv("YT_REFRESH_TOKEN") else [], st)
    words = sum(len(x["t"].split()) for sc in script["scenes"] for x in sc["dialogue"])
    log(f"  script ready: {len(script['scenes'])} scenes, {words} words")
    return script


SHORT_VERIFIED = {0, 1, 2, 4, 6}


def gen_short(st, wd, now=None):
    now = now or datetime.now(timezone.utc)
    name, instr, pool = SHORT_FORMATS[wd]
    topic_hint = random.choice(pool)
    p2 = None
    research = research_demand([f"{topic_hint} help", topic_hint], now)
    if wd in SHORT_VERIFIED:
        area = "exam" if wd == 0 else "math"
        p = make_problem("short", area, topic_hint, f"{name}: {instr}", st["titles"][-10:], now)
        try:
            p2 = make_problem("short", area, topic_hint, f"{topic_hint}. It MUST test exactly the same skill as this solved example, with new numbers (not another topic): {p['statement']}", [p["statement"]], now)
        except Exception as e:
            log("  no verified challenge question: publishing this short without one:", e)
        scenes_in = [{"kind": "hook", "heading": (p["task"] or "Can you solve it?")[:32],
                      "items": norm_items([{"k": "eq", "t": p["statement_eq"], "n": ""}] if p.get("statement_eq") else [{"k": "big", "t": p["statement"][:70]}], 3)}]
        for k in range(0, len(p["steps"]), 2):
            its = []
            for s in p["steps"][k:k + 2]:
                its.append({"k": "eq", "t": s["eq"], "n": cut(s["say"], 45)} if s["eq"] else {"k": "step", "t": cut(s["say"], 45), "n": ""})
            scenes_in.append({"kind": "example", "heading": "Step by step"[:32], "items": norm_items(its, 3)})
        scenes_in.append({"kind": "recap", "heading": "The answer", "items": norm_items([{"k": "ans", "t": p["answer_text"][:80]}], 3)})
        if p2:
            scenes_in.append({"kind": "practice", "heading": "Your turn!", "items": norm_items(
                [{"k": "q", "t": (p2["task"] or "Solve it")[:45]}] + ([{"k": "eq", "t": p2["statement_eq"]}] if p2.get("statement_eq") else
                                                                      [{"k": "q", "t": p2["statement"][:90]}]), 3)})
        facts = prob_allowed(p) + (" " + prob_allowed(p2) if p2 else "")
        listing = "\n".join(f"SCENE {i}: [{s['kind']}] heading={s['heading']} items=" + " || ".join(x['t'] + (f" ({x['n']})" if x['n'] else "") for x in s["items"])
                            for i, s in enumerate(scenes_in))
        prompt = (f"Create ONE YouTube Short (about 40 seconds spoken: 75-90 words of dialogue in total). Format: {name} - {instr}.\n"
                  f"{demand_text(research)}Avoid these recent titles: {json.dumps(st['titles'][-30:])}\n"
                  "These scenes and their on-screen items are FINAL and verified. Write the dialogue for each scene (1-2 short lines each), saying numbers "
                  "exactly as on screen, digits for numbers and words for operations. Do NOT promise a trick, shortcut or special method; only describe the method shown in the steps. Scene 0 is a 3-second hook"
                  + (" ending with 'Pause and try it'." if wd == 4 else ".") + (" The LAST scene is a challenge question for the viewer (do NOT say its answer): ALEX reads it, then SAM says 'Comment your answer below and follow for a new lesson every day'.\n"
                    if p2 else " The last scene ends with SAM saying 'Follow for a new lesson every day'.\n")
                  + listing + '\nReturn JSON: {"topic": str, "title": str (max 60 chars, search phrase first), "description": str (1-2 keyword-rich sentences), '
                  '"tags": [10-15], "hashtags": [3-4, include #Shorts], "thumb_text": str, "dialogue": [[{"s":"A"|"S","t":str}] one list per scene]}')
        last, fb = None, ""
        for _ in range(3):
            try:
                plan = llm_json(prompt + fb)
                scenes = []
                for i, s in enumerate(scenes_in):
                    raw = {"heading": s["heading"], "items": s["items"], "dialogue": plan["dialogue"][i]}
                    sc = norm_scene(raw, s["kind"] if i else "hook", s["heading"], short=True)
                    bad = bad_numbers(sc["dialogue"], " ".join(x["t"] + " " + x["n"] for x in sc["items"]) + " " + facts)
                    if bad:
                        raise ValueError(f"spoken numbers not on screen: {bad}")
                    is_ch = bool(p2) and i == len(scenes_in) - 1
                    sc["think"] = 3 if ((wd == 4 and i == 0) or is_ch) else 0
                    sc["tag"], sc["problem"] = ("YOUR TURN" if is_ch else ""), "short"
                    scenes.append(sc)
                errs = audit_script({"scenes": scenes})
                if errs:   # repair: rewrite the dialogue with the reviewers' notes (items are already verified)
                    fb = "\nFIX THESE PROBLEMS FROM THE LAST DRAFT: " + "; ".join(e["problem"] for e in errs)
                    raise ValueError("audit: " + fb[:300])
                break
            except Exception as e:
                last = e
                log("  short retry:", e)
        else:
            raise RuntimeError(f"short script failed: {last}")
    else:
        prompt = (
            f"Create ONE YouTube Short (30-45 seconds when spoken: 85-110 words of dialogue in total).\n"
            f"Today's format: {name} - {instr}. Subject idea: {topic_hint}. Avoid these recent titles: {json.dumps(st['titles'][-30:])}\n"
            f"{demand_text(research)}{ITEM_DOC}\n"
            'Return JSON: {"topic": str, "title": str (max 60 chars, hook + keyword), "description": str (1-2 keyword-rich sentences), '
            '"tags": [10-15], "hashtags": [3-4, include #Shorts], "thumb_text": str, '
            '"challenge_answer": str (the correct answer to the final question), '
            '"scenes": [4-6 objects {"kind": "hook"|"explain"|"example"|"mistake"|"practice", "heading": str max 32 chars, '
            '"items": [max 3 items, each max 45 chars], "dialogue": [1-2 short lines {"s": "A"|"S", "t": str}]}]}\n'
            "Scene 1 is a 3-second hook. The LAST scene (kind practice) asks the viewer ONE quick question about what was just taught (short items, do not reveal the answer); "
            "SAM says 'Comment your answer below and follow for a new lesson every day'. Every fact must be exactly correct.")
        plan = llm_json(prompt)
        scenes = []
        for i, raw in enumerate(plan["scenes"][:6]):
            try:
                sc = norm_scene(raw, raw.get("kind", "explain") if i else "hook", raw.get("heading", ""), short=True)
                sc["think"], sc["tag"], sc["problem"] = 0, "", ""
                if sc["kind"] == "practice":
                    sc["think"], sc["tag"] = 3, "YOUR TURN"
                scenes.append(sc)
            except Exception as e:
                log("  short scene skipped:", e)
        if len(scenes) < 3:
            raise RuntimeError("short script too small")
    script = {"kind": "short", "title": plan["title"], "topic": plan.get("topic", plan["title"]), "description": plan.get("description", ""),
              "tags": plan.get("tags", []), "hashtags": plan.get("hashtags", []), "thumb_text": plan.get("thumb_text", ""), "scenes": scenes,
              "opener": name, "format": name, "area": "math",
              "challenge": p2, "challenge_answer": (p2["answer_text"] if p2 else ("" if wd in SHORT_VERIFIED else str(plan.get("challenge_answer") or "")))}
    if wd not in SHORT_VERIFIED:
        errs = audit_script(script)
        if errs:
            raise RuntimeError("short audit errors: " + json.dumps(errs, ensure_ascii=False)[:400])
    return script


# ============================================================ VOICE (Kokoro -> edge-tts -> espeak)
_KOKORO = None
_KOKORO_FAILED = False


def get_kokoro():
    global _KOKORO, _KOKORO_FAILED
    if _KOKORO is not None or _KOKORO_FAILED:
        return _KOKORO
    try:
        from kokoro_onnx import Kokoro
        m = os.getenv("KOKORO_MODEL", "models/kokoro-v1.0.onnx")
        v = os.getenv("KOKORO_VOICES", "models/voices-v1.0.bin")
        if not (Path(m).exists() and Path(v).exists()):
            raise FileNotFoundError("kokoro model files missing")
        _KOKORO = Kokoro(m, v)
        log("Kokoro TTS ready")
    except Exception as e:
        _KOKORO_FAILED = True
        log("Kokoro unavailable, falling back to edge-tts:", e)
    return _KOKORO


def speakable(t):
    t = t.replace("**", "").replace("*", "")
    t = re.sub(r"\^\s*2\b", " squared", t)
    t = re.sub(r"\^\s*3\b", " cubed", t)
    t = re.sub(r"\^\s*(\d+)", r" to the power of \1", t)
    t = re.sub(r"(?<![\w)\].])[−-](?=\d|\()", "negative ", t)
    rep = {"²": " squared", "³": " cubed", "√": " square root of ", "π": " pi ", "×": " times ", "÷": " divided by ",
           "≤": " less than or equal to ", "≥": " greater than or equal to ", "≠": " not equal to ", "→": " to ",
           "°": " degrees", "%": " percent", "Δ": " delta ", "∞": " infinity", "−": " minus ", "=": " equals ",
           "+": " plus ", "&": " and ", "_": " "}
    for a, b in rep.items():
        t = t.replace(a, b)
    return re.sub(r"\s+", " ", t).strip()


def line_style(text, short):
    """Speaking speed tuned for friendly educational chat (Kokoro speed; 1.0 = normal)."""
    sp = 1.13 if short else 1.04
    t = text.strip()
    words = len(t.split())
    if t.endswith("?"):
        sp += 0.02
    if words <= 5:
        sp += 0.03          # quick reactions ("Exactly!", "Wait, what?")
    if re.search(r"\d", t) or re.search(r"\b(equals|squared|plus|minus|times|divided)\b", t):
        sp -= 0.05          # slow down on numbers and math so students can follow
    return max(0.9, min(1.25, sp))


def _load_audio(path):
    p = subprocess.run(["ffmpeg", "-v", "error", "-i", str(path), "-ac", "1", "-ar", str(SR), "-f", "s16le", "-"],
                       capture_output=True, check=True)
    return np.frombuffer(p.stdout, dtype=np.int16).astype(np.float32) / 32768.0


def _trim(a):
    idx = np.where(np.abs(a) > 0.012)[0]
    if len(idx) == 0:
        return a
    return a[max(0, idx[0] - int(0.03 * SR)): idx[-1] + int(0.09 * SR)]


async def _edge_save(text, voice, rate, pitch, out):
    import edge_tts
    await edge_tts.Communicate(text, voice, rate=rate, pitch=pitch).save(str(out))


def _edge_line(text, spk, sp, out):
    rate = f"{int((sp - 1.0) * 100) + 6:+d}%"
    pitch = "+3Hz" if text.strip().endswith("?") else "+0Hz"
    voice = EDGE_VOICES[spk]
    for attempt in range(3):
        try:
            asyncio.run(_edge_save(text, voice if attempt < 2 else EDGE_FALLBACK[voice], rate, pitch, out))
            if Path(out).exists() and Path(out).stat().st_size > 1000:
                return _load_audio(out)
        except Exception as e:
            log("   edge-tts retry:", e)
            time.sleep(1.5 * (attempt + 1))
    raise RuntimeError("edge-tts failed")


def _espeak_line(text, out):
    wav = str(out) + ".wav"
    subprocess.run(["espeak-ng", "-v", "en-us", "-s", "170", "-w", wav, text], check=True)
    return _load_audio(wav)


def tts_line(text, spk, short, tmp, idx):
    if flag("FAKE_TTS"):
        n = int(max(1.0, len(text.split()) * 0.34) * SR)
        return np.zeros(n, dtype=np.float32)
    clean, sp = speakable(text), line_style(text, short)
    k = get_kokoro()
    if k is not None:
        try:
            a, sr = k.create(clean, voice=KOKORO_VOICES[spk], speed=sp, lang="en-us")
            a = np.asarray(a, dtype=np.float32).flatten()
            if sr != SR:
                a = np.interp(np.linspace(0, len(a) - 1, int(len(a) * SR / sr)), np.arange(len(a)), a).astype(np.float32)
            if len(a) > SR * 0.2:
                return _trim(a)
        except Exception as e:
            log("   kokoro line failed:", e)
    out = tmp / f"line_{idx}.mp3"
    try:
        return _trim(_edge_line(clean, spk, sp, out))
    except Exception:
        return _trim(_espeak_line(clean, tmp / f"line_{idx}"))


POP_VOL = float(os.getenv("POP_VOL", "0.02"))   # volume of the little "tick" when text appears (0 = off)


def pop_sound():
    """Very soft, short 'blip' (falling tone). Raise/lower with POP_VOL, set 0 to disable."""
    n = int(0.07 * SR)
    t = np.arange(n) / SR
    ph = 2 * np.pi * np.cumsum(np.linspace(620, 430, n)) / SR
    return (np.sin(ph) * np.exp(-t * 48) * POP_VOL).astype(np.float32)


def build_audio(script, tmp, short, tail):
    """Voices every line, returns timeline + writes audio.wav (voices + soft pop on every reveal)."""
    gap_lo, gap_hi = (0.06, 0.15) if short else (0.10, 0.24)
    chunks, t, idx = [], 0.0, 0
    tl = {"events": [], "scene_starts": [], "scene_ends": [], "lines": [], "cues": []}
    reveals = []
    for si, sc in enumerate(script["scenes"]):
        lines = []
        tl["scene_starts"].append(t)
        for ln in sc["dialogue"]:
            a = tts_line(ln["t"], ln["s"], short, tmp, idx)
            idx += 1
            rms = float(np.sqrt(np.mean(a ** 2))) or 1e-4
            a = np.clip(a * float(np.clip(0.11 / rms, 0.5, 3.0)), -0.98, 0.98)
            dur = len(a) / SR
            lines.append({"start": t, "dur": dur})
            tl["cues"].append((t, t + dur, ln["t"]))
            chunks.append(a)
            gap = random.uniform(gap_lo, gap_hi)
            chunks.append(np.zeros(int(gap * SR), dtype=np.float32))
            t += dur + gap
        think = int(sc.get("think") or 0)
        think_start = t
        if think:  # silent "pause the video and try it" time with a visible countdown
            chunks.append(np.zeros(int(think * SR), dtype=np.float32))
            t += think
        scene_gap = 0.25 if short else 0.45
        chunks.append(np.zeros(int(scene_gap * SR), dtype=np.float32))
        t += scene_gap
        tl["scene_ends"].append(t)
        # reveal schedule: items appear while the hosts speak, in order
        m, n = len(sc["items"]), len(lines)
        rl = [min(n - 1, int(k * n / m)) for k in range(m)] if m else []
        events, vis = [], 0
        for j, ln in enumerate(lines):
            rev = [k for k in range(m) if rl[k] == j]
            if not rev:
                events.append({"t": ln["start"], "vis": vis, "line": j, "new": None, "first": j == 0})
            for ii, k in enumerate(rev):
                vis = k + 1
                tt = ln["start"] + ii * 0.5 * ln["dur"] / len(rev)
                events.append({"t": tt, "vis": vis, "line": j, "new": k, "first": j == 0 and ii == 0})
                reveals.append(tt)
        for k in range(think):
            events.append({"t": think_start + k, "vis": m, "line": max(0, n - 1), "new": None, "first": False, "count": think - k})
        tl["events"].append(events)
    chunks.append(np.zeros(int(tail * SR), dtype=np.float32))
    t += tail
    master = np.concatenate(chunks)
    p = pop_sound()
    for rt in reveals:
        s = int(rt * SR)
        e = min(len(master), s + len(p))
        if s < len(master):
            master[s:e] += p[: e - s]
    tl["total"] = t
    wav = tmp / "audio.wav"
    with wave.open(str(wav), "wb") as w:
        w.setnchannels(1)
        w.setsampwidth(2)
        w.setframerate(SR)
        w.writeframes((np.clip(master, -1, 1) * 32767).astype(np.int16).tobytes())
    return wav, tl


# ============================================================ DRAWING HELPERS
@lru_cache(None)
def font_path(kind):
    names = {"bold": "Poppins-Bold.ttf", "med": "Poppins-Medium.ttf", "math": "DejaVuSans-Bold.ttf", "mathr": "DejaVuSans.ttf"}
    urls = {"bold": "https://github.com/google/fonts/raw/main/ofl/poppins/Poppins-Bold.ttf",
            "med": "https://github.com/google/fonts/raw/main/ofl/poppins/Poppins-Medium.ttf"}
    name = names[kind]
    p = FONT_DIR / name
    if p.exists():
        return str(p)
    for d in ("/usr/share/fonts/truetype/google-fonts", "/usr/share/fonts/truetype/dejavu", "/usr/share/fonts/truetype/poppins"):
        q = Path(d) / name
        if q.exists():
            return str(q)
    if kind in urls:
        try:
            r = requests.get(urls[kind], timeout=60)
            r.raise_for_status()
            FONT_DIR.mkdir(exist_ok=True)
            p.write_bytes(r.content)
            return str(p)
        except Exception:
            pass
    for fb in ("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf", "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf"):
        if Path(fb).exists():
            return fb
    raise RuntimeError("no usable font found")


@lru_cache(None)
def font(kind, size):
    return ImageFont.truetype(font_path(kind), int(max(10, round(size))))


MATH_RE = re.compile(r"[²³√π×÷≤≥≠→−∞°ΔΣ∑∫±₀₁₂₃₄₅₆₇₈₉⁰¹⁴⁵⁶⁷⁸⁹θ∠△≈∈∉∪∩⊂λμσφ]")


def mf(fnt, word):
    if not MATH_RE.search(word):
        return fnt
    return font("mathr" if "Medium" in str(getattr(fnt, "path", "")) else "math", fnt.size)


def tok(text):
    words, hl = [], False
    for part in re.split(r"(\*\*)", text):
        if part == "**":
            hl = not hl
            continue
        for w in part.split():
            words.append((w, hl))
    return words


def wrap(text, fnt, maxw):
    lines, cur, curw, sp = [], [], 0.0, fnt.getlength(" ")
    for w, h in tok(text):
        ww = mf(fnt, w).getlength(w) + (12 if h else 0)
        if cur and curw + sp + ww > maxw:
            lines.append(cur)
            cur, curw = [(w, h)], ww
        else:
            curw += (sp if cur else 0) + ww
            cur.append((w, h))
    if cur:
        lines.append(cur)
    return lines or [[("", False)]]


def draw_lines(d, x, y, lines, fnt, color, lh, align="left", width=0, hl=True, mode="all"):
    """mode: all = text + highlight, text = plain text only, hl = only the highlighted words (rect + dark text)."""
    sp = fnt.getlength(" ")
    _, t, _, b = fnt.getbbox("Hg", anchor="la")
    for ln in lines:
        lw = sum(mf(fnt, w).getlength(w) + (12 if hh else 0) for w, hh in ln) + sp * (len(ln) - 1)
        cx = x if align == "left" else x + (width - lw) / 2
        for i, (w, h) in enumerate(ln):
            f2 = mf(fnt, w)
            ww = f2.getlength(w)
            ishl = bool(h and hl)
            prv = i > 0 and bool(ln[i - 1][1] and hl)
            nxt = i + 1 < len(ln) and bool(ln[i + 1][1] and hl)
            if ishl and i > 0 and not prv:
                cx += 6
            if ishl and mode != "text":
                d.rounded_rectangle([cx - 6, y + t - 3, cx + ww + (sp if nxt else 0) + 6, y + b + 3], radius=8, fill=YEL)
                d.text((cx, y), w, font=f2, fill=NAVY, anchor="la")
            elif mode != "hl":
                d.text((cx, y), w, font=f2, fill=color, anchor="la")
            cx += ww + sp + (6 if (ishl and not nxt) else 0)
        y += lh
    return y


def wordmark(fs, dark_text=False):
    S = 3
    f = font("bold", fs * S)
    d0 = ImageDraw.Draw(Image.new("RGBA", (10, 10)))
    a, b = d0.textlength("high", font=f), d0.textlength("lit", font=f)
    pad = fs * S * 0.12
    W, H = int(a + b + pad * 2.2), int(fs * S * 1.5)
    im = Image.new("RGBA", (W, H), (0, 0, 0, 0))
    d = ImageDraw.Draw(im)
    cy = H / 2
    d.text((0, cy), "high", font=f, fill=NAVY if dark_text else WHITE, anchor="lm")
    d.rounded_rectangle([a + pad * 0.2, cy - fs * S * 0.58, a + b + pad * 1.6, cy + fs * S * 0.46], radius=fs * S * 0.1, fill=YEL)
    d.text((a + pad * 0.9, cy), "lit", font=f, fill=NAVY, anchor="lm")
    return im.resize((W // S, H // S), Image.LANCZOS)


# ---- safe graph evaluator
_FN = {"sin": math.sin, "cos": math.cos, "tan": math.tan, "sqrt": math.sqrt, "log": math.log, "ln": math.log,
       "exp": math.exp, "abs": abs, "pi": math.pi, "e": math.e, "asin": math.asin, "acos": math.acos, "atan": math.atan}
_OK = (ast.Expression, ast.BinOp, ast.UnaryOp, ast.Constant, ast.Name, ast.Call, ast.Load, ast.Add, ast.Sub, ast.Mult,
       ast.Div, ast.Pow, ast.USub, ast.UAdd, ast.Mod)


def safe_fn(expr):
    tree = ast.parse(expr.replace("^", "**").replace("−", "-"), mode="eval")
    for n in ast.walk(tree):
        if not isinstance(n, _OK):
            raise ValueError("bad expr")
        if isinstance(n, ast.Name) and n.id not in _FN and n.id != "x":
            raise ValueError("bad name")
        if isinstance(n, ast.Call) and not (isinstance(n.func, ast.Name) and n.func.id in _FN):
            raise ValueError("bad call")
        if isinstance(n, ast.Constant) and (not isinstance(n.value, (int, float)) or abs(n.value) > 1000):
            raise ValueError("bad const")
    code = compile(tree, "<f>", "eval")
    return lambda x: eval(code, {"__builtins__": {}}, {**_FN, "x": x})


def _nice(v):
    if v <= 0:
        return 1
    e = 10 ** math.floor(math.log10(v))
    for m in (1, 2, 5, 10):
        if v <= m * e:
            return m * e
    return 10 * e


def _ticks(a, b):
    step, out = _nice((b - a) / 5), []
    v = math.ceil(a / step) * step
    while v <= b + 1e-9:
        out.append(round(v, 10))
        v += step
    return out


# ---- themes: dark navy (hook, end card, thumbnail) and light "graph paper" (lesson slides: easier on the eyes for numbers)
THEME_PREF = os.getenv("THEME", "light").strip().lower()
DARK = {"name": "dark", "top": NAVY, "bot": NAVY2, "grid": (16, 38, 88), "fg": WHITE, "mute": MUTE, "panel": PANEL,
        "pfg": WHITE, "ggrid": (40, 70, 130), "gaxis": WHITE, "pill": False}
LIGHT = {"name": "light", "top": (251, 252, 255), "bot": (234, 241, 252), "grid": (219, 229, 246), "fg": NAVY,
         "mute": (88, 106, 150), "panel": (225, 234, 252), "pfg": NAVY, "ggrid": (203, 216, 240), "gaxis": NAVY, "pill": True}


def theme_for(sc):
    return DARK if (sc["type"] == "hook" or THEME_PREF == "dark") else LIGHT


def clamp(v, a=0.0, b=1.0):
    return max(a, min(b, v))


def ease(t):
    t = clamp(t)
    return t * t * (3 - 2 * t)


def ease_back(t):
    t = clamp(t)
    c1 = 1.70158
    c3 = c1 + 1
    return 1 + c3 * (t - 1) ** 3 + c1 * (t - 1) ** 2


def draw_circle_graph(spec, w, h, s, th, upto=1.0):
    """Equal-scale circle with centre and radius (a y=f(x) plot can only draw half a circle and distorts it)."""
    cx, cy, r = float(spec["h"]), float(spec["k"]), float(spec["r"])
    if r <= 0:
        raise ValueError("radius")
    im = Image.new("RGBA", (w, h), (0, 0, 0, 0))
    d = ImageDraw.Draw(im)
    d.rounded_rectangle([0, 0, w - 1, h - 1], radius=int(20 * s), fill=th["panel"] + (255,))
    L, R, T, B = int(52 * s), w - int(18 * s), int(50 * s), h - int(36 * s)
    sc_ = min(R - L, B - T) / (2.0 * r * 1.35)
    ox, oy = (L + R) / 2, (T + B) / 2
    px = lambda x: ox + (x - cx) * sc_
    py = lambda y: oy - (y - cy) * sc_
    x0, x1 = cx - (ox - L) / sc_, cx + (R - ox) / sc_
    y0, y1 = cy - (B - oy) / sc_, cy + (oy - T) / sc_
    tf = font("med", 20 * s)
    for tx in _ticks(x0, x1):
        d.line([(px(tx), T), (px(tx), B)], fill=th["ggrid"], width=1)
        d.text((px(tx), B + 5 * s), f"{tx:g}", font=tf, fill=th["mute"], anchor="mt")
    for ty in _ticks(y0, y1):
        d.line([(L, py(ty)), (R, py(ty))], fill=th["ggrid"], width=1)
        d.text((L - 6 * s, py(ty)), f"{ty:g}", font=tf, fill=th["mute"], anchor="rm")
    if y0 <= 0 <= y1:
        d.line([(L, py(0)), (R, py(0))], fill=th["gaxis"], width=2)
    if x0 <= 0 <= x1:
        d.line([(px(0), T), (px(0), B)], fill=th["gaxis"], width=2)
    layer = Image.new("RGBA", (w, h), (0, 0, 0, 0))
    ld = ImageDraw.Draw(layer)
    N = 240
    pts = [(px(cx + r * math.cos(2 * math.pi * i / N)), py(cy + r * math.sin(2 * math.pi * i / N))) for i in range(int(N * max(0.04, upto)) + 1)]
    lw = max(4, int(6 * s))
    if th["pill"]:
        ld.line(pts, fill=NAVY, width=lw + 6, joint="curve")
    ld.line(pts, fill=YEL, width=lw, joint="curve")
    if upto >= 1:
        ex, ey = px(cx + r * math.cos(0.7)), py(cy + r * math.sin(0.7))
        ld.line([(px(cx), py(cy)), (ex, ey)], fill=NAVY if th["pill"] else WHITE, width=max(3, int(4 * s)))
        ld.ellipse([px(cx) - 8 * s, py(cy) - 8 * s, px(cx) + 8 * s, py(cy) + 8 * s], fill=YEL, outline=NAVY, width=3)
        ld.text(((px(cx) + ex) / 2 + 8 * s, (py(cy) + ey) / 2 - 8 * s), f"r = {r:g}", font=font("bold", 24 * s), fill=NAVY if th["pill"] else WHITE, anchor="lb")
        ld.text((px(cx) - 12 * s, py(cy) + 12 * s), f"({cx:g}, {cy:g})", font=font("bold", 22 * s), fill=NAVY if th["pill"] else WHITE, anchor="rt")
    mask = Image.new("L", (w, h), 0)
    ImageDraw.Draw(mask).rectangle([L, T, R, B], fill=255)
    layer.putalpha(ImageChops.multiply(layer.getchannel("A"), mask))
    im.alpha_composite(layer)
    if spec.get("label"):
        ImageDraw.Draw(im).text((L + 8 * s, 10 * s), str(spec["label"])[:40], font=font("bold", 24 * s), fill=NAVY if th["pill"] else YEL, anchor="la")
    return im


def draw_graph(spec, w, h, s, th, upto=1.0):
    if str(spec.get("type")) == "circle":
        return draw_circle_graph(spec, w, h, s, th, upto)
    fn = safe_fn(str(spec["expr"]))
    x0, x1 = float(spec.get("xmin", -5)), float(spec.get("xmax", 5))
    if not x1 > x0:
        raise ValueError("range")
    xs = [x0 + (x1 - x0) * i / 499 for i in range(500)]
    ys = []
    for x in xs:
        try:
            y = float(fn(x))
            ys.append(y if math.isfinite(y) else float("nan"))
        except Exception:
            ys.append(float("nan"))
    fin = sorted(y for y in ys if y == y)
    if len(fin) < 20:
        raise ValueError("no data")
    lo, hi = fin[int(len(fin) * 0.02)], fin[int(len(fin) * 0.98)]
    if hi - lo < 1e-6:
        lo, hi = lo - 1, hi + 1
    pv = (hi - lo) * 0.12
    lo, hi = lo - pv, hi + pv
    im = Image.new("RGBA", (w, h), (0, 0, 0, 0))
    d = ImageDraw.Draw(im)
    d.rounded_rectangle([0, 0, w - 1, h - 1], radius=int(20 * s), fill=th["panel"] + (255,))
    L, R, T, B = int(52 * s), w - int(18 * s), int(50 * s), h - int(36 * s)
    px = lambda x: L + (x - x0) / (x1 - x0) * (R - L)
    py = lambda y: B - (y - lo) / (hi - lo) * (B - T)
    tf = font("med", 20 * s)
    for tx in _ticks(x0, x1):
        d.line([(px(tx), T), (px(tx), B)], fill=th["ggrid"], width=1)
        d.text((px(tx), B + 5 * s), f"{tx:g}", font=tf, fill=th["mute"], anchor="mt")
    for ty in _ticks(lo, hi):
        d.line([(L, py(ty)), (R, py(ty))], fill=th["ggrid"], width=1)
        d.text((L - 6 * s, py(ty)), f"{ty:g}", font=tf, fill=th["mute"], anchor="rm")
    if lo <= 0 <= hi:
        d.line([(L, py(0)), (R, py(0))], fill=th["gaxis"], width=2)
    if x0 <= 0 <= x1:
        d.line([(px(0), T), (px(0), B)], fill=th["gaxis"], width=2)
    layer = Image.new("RGBA", (w, h), (0, 0, 0, 0))
    ld = ImageDraw.Draw(layer)
    rng, segs, seg = hi - lo, [], []
    limit = max(2, int(500 * upto))
    for idx, (x, y) in enumerate(zip(xs, ys)):
        if idx >= limit:
            break
        if y != y or y < lo - rng or y > hi + rng:
            if len(seg) > 1:
                segs.append(seg)
            seg = []
            continue
        seg.append((px(x), py(y)))
    if len(seg) > 1:
        segs.append(seg)
    lw = max(4, int(6 * s))
    for sg in segs:
        if th["pill"]:
            ld.line(sg, fill=NAVY, width=lw + 6, joint="curve")
        ld.line(sg, fill=YEL, width=lw, joint="curve")
    if upto < 1 and segs:  # pen dot at the tip of the curve while it is being drawn
        tx_, ty_ = segs[-1][-1]
        ld.ellipse([tx_ - 9 * s, ty_ - 9 * s, tx_ + 9 * s, ty_ + 9 * s], fill=YEL, outline=NAVY, width=3)
    mask = Image.new("L", (w, h), 0)
    ImageDraw.Draw(mask).rectangle([L, T, R, B], fill=255)
    layer.putalpha(ImageChops.multiply(layer.getchannel("A"), mask))
    im.alpha_composite(layer)
    if spec.get("label"):
        ImageDraw.Draw(im).text((L + 8 * s, 10 * s), str(spec["label"])[:40], font=font("bold", 24 * s),
                                fill=NAVY if th["pill"] else YEL, anchor="la")
    return im


# ============================================================ SLIDE RENDERER (with write-on, arrows, pop, sweeps)
class Canvas:
    def __init__(self, short):
        self.short = short
        self.W, self.H = (720, 1280) if short else (1280, 720)
        self.s = 1.0
        self.mx = 48 if short else 90
        self._bg, self._wm = {}, {}

    def bg(self, th=DARK):
        if th["name"] not in self._bg:
            W, H = self.W, self.H
            im = Image.new("RGB", (W, H), th["top"])
            d = ImageDraw.Draw(im)
            for y in range(H):
                t = y / H
                d.line([(0, y), (W, y)], fill=tuple(int(th["top"][i] * (1 - t) + th["bot"][i] * t) for i in range(3)))
            for x in range(0, W, 64):
                d.line([(x, 0), (x, H)], fill=th["grid"])
            for y in range(0, H, 64):
                d.line([(0, y), (W, y)], fill=th["grid"])
            if th["pill"]:
                d.rectangle([0, 0, W, 10], fill=YEL)
            self._bg[th["name"]] = im
        return self._bg[th["name"]]

    def wm(self, th):
        if th["name"] not in self._wm:
            wm = wordmark(34 if self.short else 30, dark_text=th["pill"])
            wm.putalpha(wm.getchannel("A").point(lambda v: int(v * 0.88)))
            self._wm[th["name"]] = wm
        return self._wm[th["name"]]


BSPEC = {"bullet": ("med", 38), "step": ("med", 38), "q": ("med", 40), "choice": ("med", 34), "ans": ("bold", 40),
         "note": ("med", 30), "big": ("bold", 60), "big2": ("bold", 46), "eq": ("math", 54)}


def _lw(fnt, ln):
    sp = fnt.getlength(" ")
    return sum(mf(fnt, w).getlength(w) + (12 if hh else 0) for w, hh in ln) + sp * (len(ln) - 1)


def make_block(cv, it, w, f, center, stepno, th):
    s = cv.s * f
    k = it["k"]
    if center and k in ("bullet", "step", "note", "q"):
        k = "big2"
    kind, size = BSPEC[k]
    fnt = font(kind, size * s)
    ind = {"bullet": 46, "step": 62, "q": 26, "choice": 22, "ans": 22, "eq": 24}.get(k, 0) * s
    boxed = k in ("choice", "ans", "eq")
    pad = 16 * s if boxed else 0
    iw = w - 2 * ind if boxed else w - ind
    if k == "eq":  # equations stay on ONE line: shrink the font instead of wrapping
        for sh in (1.0, 0.92, 0.84, 0.76, 0.68, 0.6):
            fnt = font(kind, size * s * sh)
            if len(wrap(it["t"], fnt, iw)) == 1:
                break
    lh = fnt.size * 1.32
    lines = wrap(it["t"], fnt, iw)
    h = len(lines) * lh
    nl, nf = [], None
    if it.get("n"):
        nf = font("med", 28 * s)
        nl = wrap(it["n"], nf, iw)
        h += len(nl) * nf.size * 1.3 + 6 * s
    h += 2 * pad
    # row geometry (for the line-by-line "writing" animation)
    rows, yy = [], pad
    for ln in lines:
        lw = _lw(fnt, ln)
        x0 = (w - lw) / 2 if k in ("big", "big2") else (ind + (w - 2 * ind - lw) / 2 if k == "eq" else ind)
        rows.append((yy, yy + lh, x0, x0 + lw))
        yy += lh
    yy += 4 * s
    for ln in nl:
        lw = _lw(nf, ln)
        x0 = ind + (w - 2 * ind - lw) / 2 if k == "eq" else ind
        rows.append((yy, yy + nf.size * 1.3, x0, x0 + lw))
        yy += nf.size * 1.3
    return {"k": k, "lines": lines, "fnt": fnt, "lh": lh, "ind": ind, "pad": pad, "nl": nl, "nf": nf, "h": h, "w": w,
            "step": stepno, "s": s, "th": th, "rows": rows, "has_hl": any(hh for ln in lines for _, hh in ln), "arrow": None}


def draw_block(d, b, x, y, part="all"):
    """part: all | bg (shapes) | text (plain text) | hl (highlighted words only)"""
    k, s, w, fnt, lh, ind, pad, th = b["k"], b["s"], b["w"], b["fnt"], b["lh"], b["ind"], b["pad"], b["th"]
    fg = th["fg"]
    bg = part in ("all", "bg")
    mode = {"all": "all", "text": "text", "hl": "hl"}.get(part)
    boxed = k in ("choice", "ans", "eq")
    ty = y + (pad if boxed else 0)
    yy = ty + len(b["lines"]) * lh
    if k == "bullet":
        if bg:
            d.ellipse([x + 8 * s, y + lh * 0.5 - 9 * s, x + 26 * s, y + lh * 0.5 + 9 * s], fill=YEL,
                      outline=NAVY if th["pill"] else None, width=3 if th["pill"] else 0)
        if mode:
            draw_lines(d, x + ind, ty, b["lines"], fnt, fg, lh, mode=mode)
    elif k == "step":
        if bg:
            r = 24 * s
            d.ellipse([x, y + lh * 0.5 - r, x + 2 * r, y + lh * 0.5 + r], fill=YEL)
            d.text((x + r, y + lh * 0.5), str(b["step"]), font=font("bold", 28 * s), fill=NAVY, anchor="mm")
        if mode:
            draw_lines(d, x + ind, ty, b["lines"], fnt, fg, lh, mode=mode)
    elif k == "q":
        if bg:
            d.rounded_rectangle([x, y, x + 8 * s, y + b["h"]], radius=3, fill=YEL)
        if mode:
            draw_lines(d, x + ind, ty, b["lines"], fnt, fg, lh, mode=mode)
    elif boxed:
        if bg:
            d.rounded_rectangle([x, y, x + w, y + b["h"]], radius=16 * s, fill=YEL if k == "ans" else th["panel"])
            if k == "eq" and th["pill"]:
                d.rounded_rectangle([x, y, x + 10 * s, y + b["h"]], radius=5, fill=YEL)
        if mode:
            draw_lines(d, x + ind, ty, b["lines"], fnt, NAVY if k == "ans" else th["pfg"], lh,
                       align="center" if k == "eq" else "left", width=w - 2 * ind, hl=(k != "ans"), mode=mode)
    elif k in ("big", "big2"):
        if mode:
            draw_lines(d, x, ty, b["lines"], fnt, fg, lh, align="center", width=w, mode=mode)
    else:
        if mode:
            draw_lines(d, x + ind, ty, b["lines"], fnt, th["mute"], lh, mode=mode)
    if b["nl"] and part in ("all", "text"):
        draw_lines(d, x + ind, yy + 4 * s, b["nl"], b["nf"], NAVY if k == "ans" else th["mute"], b["nf"].size * 1.3,
                   align="center" if k == "eq" else "left", width=w - 2 * ind, hl=False, mode="text" if part == "text" else "all")


def draw_arrow(img, cx, cy, size, th, scale=1.0, alpha=1.0):
    """Little yellow down-arrow between consecutive steps (the 'flow' of a solution)."""
    if scale <= 0.02 or alpha <= 0:
        return
    S = max(8, int(size * scale))
    tmp = Image.new("RGBA", (S * 2, S * 2), (0, 0, 0, 0))
    d = ImageDraw.Draw(tmp)
    c = S
    sw, hw = S * 0.17, S * 0.5
    pts = [(c - sw, c - S * 0.5), (c + sw, c - S * 0.5), (c + sw, c), (c + hw, c), (c, c + S * 0.5), (c - hw, c), (c - sw, c)]
    d.polygon(pts, fill=YEL, outline=NAVY if th["pill"] else None, width=3 if th["pill"] else 0)
    if alpha < 1:
        tmp.putalpha(tmp.getchannel("A").point(lambda v: int(v * alpha)))
    img.paste(tmp, (int(cx - c), int(cy - c)), tmp)


def prepare(cv, sc):
    W, H, s, mx, short = cv.W, cv.H, cv.s, cv.mx, cv.short
    th = theme_for(sc)
    center = sc["type"] == "hook"
    P = {"blocks": [], "graph": None, "gspec": None, "tag": sc.get("tag") or TAGS.get(sc["kind"], ""), "tag_font": font("bold", 24 * s), "th": th}
    P["tag_xy"] = (mx, 188 * s if short else 56 * s)
    hsize = (76 if center else (56 if short else 54)) * s
    P["head_font"] = font("bold", hsize)
    P["head_lines"] = wrap(sc["heading"], P["head_font"], W - 2 * mx)[:3]
    P["head_lh"] = hsize * 1.22
    P["head_w"], P["head_x"] = W - 2 * mx, mx
    P["head_align"] = "center" if center else "left"
    if center:
        P["tag"] = ""
        P["head_y"] = H * (0.30 if short else 0.20)
    else:
        P["head_y"] = (232 if short else 100) * s
    hb = P["head_y"] + len(P["head_lines"]) * P["head_lh"]
    P["accent"] = None if center else [mx, hb + 10 * s, mx + 90 * s, hb + 18 * s]
    y0 = hb + 44 * s
    bottom = H - (430 if short else 110) * s
    P["outro"] = sc["kind"] == "outro" and not short
    if P["outro"]:
        bottom = int(H * 0.50)   # the lower half is kept free for YouTube end-screen elements
    cx0, cw = mx, W - 2 * mx
    if sc["type"] == "graph" and sc["graph"]:
        try:
            if short:
                gw, gh = W - 2 * mx, int(320 * s)
                pos = (mx, int(y0))
                y0 += gh + 24 * s
            else:
                gw, gh = int(W * 0.44), int(H * 0.58)
                pos = (mx, int(y0))
                cx0, cw = mx + gw + 40 * s, W - mx - (mx + gw + 40 * s)
            P["graph"] = (draw_graph(sc["graph"], gw, gh, s, th), pos)
            P["gspec"] = (sc["graph"], gw, gh, pos)
        except Exception as e:
            log("  graph skipped:", e)
    avail = bottom - y0
    starts = (1.55, 1.4, 1.25, 1.1, 1.0, 0.9, 0.8, 0.7, 0.6, 0.52) if short else (1.25, 1.15, 1.05, 1.0, 0.9, 0.8, 0.7, 0.62, 0.55)
    arrow_pair = lambda a, b: (not center) and a["k"] in ("step", "eq", "q") and b["k"] in ("step", "eq", "ans")
    for f in starts:
        blocks, sn = [], 0
        for it in sc["items"]:
            if it["k"] == "step":
                sn += 1
            blocks.append(make_block(cv, it, cw, f, center, sn, th))
        gaps = [(52 if arrow_pair(blocks[i - 1], blocks[i]) else 26) * s * f for i in range(1, len(blocks))]
        total = sum(b["h"] for b in blocks) + sum(gaps)
        if total <= avail:
            break
    place = 0.45 if short else 0.3
    y = y0 + (max(0, avail - total) * place if not P["graph"] else 0)
    for i, b in enumerate(blocks):
        b["x"], b["y"] = cx0, y
        if i > 0 and arrow_pair(blocks[i - 1], b):
            both_steps = blocks[i - 1]["k"] == "step" and b["k"] == "step"
            ax = cx0 + (blocks[i - 1]["s"] * 24 if both_steps else cw / 2)
            b["arrow"] = (ax, y - gaps[i - 1] / 2, 38 * s * f)
        y += b["h"] + (gaps[i] if i < len(gaps) else 0)
    P["blocks"] = blocks
    return P


def _row_mask(b, q, size):
    """Line-by-line left-to-right wipe (like writing by hand). Returns mask and pen position."""
    W, H = size
    m = Image.new("L", (W, H), 0)
    md = ImageDraw.Draw(m)
    rows = b["rows"]
    n = len(rows)
    if n == 0:
        return m, None
    t = clamp(q) * n
    pen = None
    for i, (r0, r1, x0, x1) in enumerate(rows):
        f = 1.0 if t >= i + 1 else (t - i if t > i else 0.0)
        if f > 0:
            edge = x0 + (x1 - x0) * f
            md.rectangle([0, int(r0) - 3, int(edge) + 2, int(r1) + 3], fill=255)
            if f < 1.0:
                pen = (edge, r0 + 2, r1 - 2)
    return m, pen


def paint_block_anim(img, b, p, cv):
    s = b["s"]
    W, H = int(b["w"]) + 12, int(b["h"]) + 12
    x, y = int(b["x"]), int(b["y"])
    if b["k"] == "ans":  # answer pops in
        sc_ = 0.7 + 0.3 * ease_back(p)
        tmp = Image.new("RGBA", (W, H), (0, 0, 0, 0))
        draw_block(ImageDraw.Draw(tmp), b, 0, 0, "all")
        tmp.putalpha(tmp.getchannel("A").point(lambda v: int(v * clamp(p / 0.3))))
        nw, nh = max(2, int(W * sc_)), max(2, int(H * sc_))
        tmp = tmp.resize((nw, nh), Image.LANCZOS)
        img.paste(tmp, (int(x + b["w"] / 2 - nw / 2), int(y + b["h"] / 2 - nh / 2)), tmp)
    else:
        a = ease(p / 0.2)
        bg = Image.new("RGBA", (W, H), (0, 0, 0, 0))
        draw_block(ImageDraw.Draw(bg), b, 0, 0, "bg")
        bg.putalpha(bg.getchannel("A").point(lambda v: int(v * a)))
        img.paste(bg, (x, y + int((1 - a) * 14 * cv.s)), bg)
        q = clamp((p - 0.1) / 0.65)
        if q > 0:
            tx = Image.new("RGBA", (W, H), (0, 0, 0, 0))
            draw_block(ImageDraw.Draw(tx), b, 0, 0, "text")
            mask, pen = _row_mask(b, q, (W, H))
            tx.putalpha(ImageChops.multiply(tx.getchannel("A"), mask))
            img.paste(tx, (x, y), tx)
            if pen and q < 1:
                ImageDraw.Draw(img).rounded_rectangle([x + pen[0], y + pen[1], x + pen[0] + 5 * s, y + pen[2]], radius=2, fill=YEL)
        hp = clamp((p - 0.7) / 0.3)
        if hp > 0 and b["has_hl"]:
            hl = Image.new("RGBA", (W, H), (0, 0, 0, 0))
            draw_block(ImageDraw.Draw(hl), b, 0, 0, "hl")
            m = Image.new("L", (W, H), 0)
            ImageDraw.Draw(m).rectangle([0, 0, int(W * hp), H], fill=255)
            hl.putalpha(ImageChops.multiply(hl.getchannel("A"), m))
            img.paste(hl, (x, y), hl)
    if b["arrow"]:
        ax, ay, asz = b["arrow"]
        draw_arrow(img, ax, ay, asz, b["th"], scale=ease_back(p / 0.45), alpha=clamp(p / 0.25))


def _header(d, P, th):
    if P["tag"]:
        tx, ty = P["tag_xy"]
        if th["pill"]:
            tw = P["tag_font"].getlength(P["tag"])
            d.rounded_rectangle([tx - 12, ty - 6, tx + tw + 12, ty + P["tag_font"].size + 8], radius=14, fill=YEL)
            d.text((tx, ty), P["tag"], font=P["tag_font"], fill=NAVY, anchor="la")
        else:
            d.text((tx, ty), P["tag"], font=P["tag_font"], fill=YEL, anchor="la")
    draw_lines(d, P["head_x"], P["head_y"], P["head_lines"], P["head_font"], th["fg"], P["head_lh"], P["head_align"], P["head_w"])
    if P["accent"]:
        d.rounded_rectangle(P["accent"], radius=4, fill=YEL)


def render(cv, P, vis, new=None, p=1.0, caption=None, frac=0.0, intro=1.0, count=None):
    th = P["th"]
    img = cv.bg(th).copy()
    if intro >= 1:
        _header(ImageDraw.Draw(img), P, th)
    else:  # heading slides in
        e = ease(intro)
        lay = Image.new("RGBA", img.size, (0, 0, 0, 0))
        _header(ImageDraw.Draw(lay), P, th)
        lay.putalpha(lay.getchannel("A").point(lambda v: int(v * e)))
        dx, dy = (0, int((1 - e) * 36)) if P["head_align"] == "center" else (int(-(1 - e) * 70), 0)
        img.paste(lay, (dx, dy), lay)
    if P["graph"]:
        g = P["graph"][0]
        if intro < 1 and P["gspec"]:
            try:
                spec, gw, gh, pos = P["gspec"]
                g = draw_graph(spec, gw, gh, cv.s, th, upto=max(0.04, ease(intro)))
            except Exception:
                pass
        img.paste(g, P["graph"][1], g)
    d = ImageDraw.Draw(img)
    for i, b in enumerate(P["blocks"][:vis]):
        if i == new and p < 1:
            paint_block_anim(img, b, p, cv)
            d = ImageDraw.Draw(img)
        else:
            draw_block(d, b, b["x"], b["y"])
            if b["arrow"]:
                ax, ay, asz = b["arrow"]
                draw_arrow(img, ax, ay, asz, th)
    if caption:
        txt, spk = caption
        for size in (34, 30, 26):
            fnt = font("bold", size * cv.s)
            lines = wrap(txt.replace("**", ""), fnt, cv.W - 2 * cv.mx - 36)
            if len(lines) <= 4:
                break
        lh = fnt.size * 1.3
        hh = len(lines) * lh + 28 * cv.s
        y = 880 * cv.s
        ov = Image.new("RGBA", img.size, (0, 0, 0, 0))
        ImageDraw.Draw(ov).rounded_rectangle([cv.mx, y, cv.W - cv.mx, y + hh], radius=22, fill=(6, 18, 48, 232))
        img = Image.alpha_composite(img.convert("RGBA"), ov).convert("RGB")
        draw_lines(ImageDraw.Draw(img), cv.mx + 18, y + 14 * cv.s, lines, fnt, WHITE if spk == "A" else YEL, lh,
                   "center", cv.W - 2 * cv.mx - 36, hl=False)
    if P.get("outro"):  # end-screen page: slots for the two videos YouTube end-screen elements + subscribe button
        dd = ImageDraw.Draw(img)
        sw, sh = int(280 * cv.s), int(58 * cv.s)
        sx, sy = cv.W // 2 - sw // 2, int(cv.H * 0.615)
        dd.rounded_rectangle([sx, sy, sx + sw, sy + sh], radius=sh // 2, fill=(229, 45, 39))
        dd.text((sx + sw // 2, sy + sh // 2), "SUBSCRIBE", font=font("bold", 30 * cv.s), fill=WHITE, anchor="mm")
        gap, top = int(40 * cv.s), int(cv.H * 0.745)
        bw, bh = (cv.W - 2 * cv.mx - gap) // 2, int(cv.H * 0.21)
        for k, lab in enumerate(("Watch next lesson", "More lessons")):
            x0 = cv.mx + k * (bw + gap)
            dd.rounded_rectangle([x0, top, x0 + bw, top + bh], radius=int(18 * cv.s), outline=YEL, width=3, fill=(22, 44, 96))
            dd.text((x0 + bw // 2, top + bh // 2), lab, font=font("med", 28 * cv.s), fill=(200, 210, 235), anchor="mm")
    if count is not None:  # "pause and try it" countdown
        r = int(40 * cv.s)
        bx, by = (cv.W // 2 - 150, cv.H - 110) if cv.short else (cv.mx + r, cv.H - r - 30)
        dd = ImageDraw.Draw(img)
        dd.ellipse([bx - r, by - r, bx + r, by + r], fill=YEL, outline=NAVY, width=4)
        dd.text((bx, by), str(count), font=font("bold", 46 * cv.s), fill=NAVY, anchor="mm")
        dd.text((bx + r + 18, by), "Pause and try it!", font=font("bold", 34 * cv.s), fill=th["fg"], anchor="lm")
    wm = cv.wm(th)
    wx, wy = ((40, 112) if cv.short else (cv.W - wm.width - 40, cv.H - wm.height - 22))
    img.paste(wm, (wx, wy), wm)
    if not cv.short:
        dd = ImageDraw.Draw(img)
        dd.rectangle([0, cv.H - 6, cv.W, cv.H], fill=th["grid"])
        dd.rectangle([0, cv.H - 6, int(cv.W * frac), cv.H], fill=YEL)
    return img


def endcard(cv):
    img = cv.bg(DARK).copy()
    d = ImageDraw.Draw(img)
    wm = wordmark(110)
    img.paste(wm, ((cv.W - wm.width) // 2, int(cv.H * 0.30)), wm)
    d.text((cv.W / 2, cv.H * 0.30 + wm.height + 40), "New lessons every week", font=font("bold", 44), fill=WHITE, anchor="mm")
    d.text((cv.W / 2, cv.H * 0.30 + wm.height + 110), "Comment the topic you want next", font=font("med", 32), fill=MUTE, anchor="mm")
    d.rounded_rectangle([cv.W / 2 - 80, cv.H * 0.30 + wm.height + 150, cv.W / 2 + 80, cv.H * 0.30 + wm.height + 158], radius=4, fill=YEL)
    return img


def run(cmd):
    p = subprocess.run(cmd, capture_output=True, text=True)
    if p.returncode != 0:
        raise RuntimeError(f"{cmd[0]} failed: {p.stderr[-800:]}")


def render_video(script, tl, wav, short, fdir, out_mp4):
    TF = 1 / 20  # animation frame rate (20 fps while something moves, long holds in between)
    cv = Canvas(short)
    frames, n, prev = [], 0, None

    def save(im):
        nonlocal n
        pth = fdir / f"f{n:05d}.png"
        im.save(pth, compress_level=1)
        n += 1
        return str(pth)

    flat = []
    for si, sc in enumerate(script["scenes"]):
        for ev in tl["events"][si]:
            flat.append((si, ev))
    for gi, (si, ev) in enumerate(flat):
        sc = script["scenes"][si]
        if ev["first"] or gi == 0:
            P = prepare(cv, sc)
        nxt = flat[gi + 1][1]["t"] if gi + 1 < len(flat) else tl["total"]
        dur = max(0.05, nxt - ev["t"])
        cap = None
        if short:
            ln = sc["dialogue"][ev["line"]]
            cap = (ln["t"], ln["s"])
        frac = ev["t"] / tl["total"]
        full = render(cv, P, ev["vis"], None, 1.0, cap, frac, count=ev.get("count"))
        new = ev["new"]
        scene_change = ev["first"] and prev is not None
        nf = 0
        if ev["first"]:
            nf = 14
        elif new is not None:
            nf = 8 if P["blocks"][new]["k"] == "ans" else 12
        nf = min(nf, int((dur - 0.12) / TF))
        anim = []
        if nf >= 4:
            for k in range(nf):
                pk = (k + 1) / nf
                im = render(cv, P, ev["vis"], new, pk if new is not None else 1.0, cap, frac,
                            intro=pk if ev["first"] else 1.0)
                if scene_change and k < 5:
                    im = Image.blend(prev, im, (k + 1) / 6)
                anim.append(im)
        for im in anim:
            frames.append((save(im), TF))
            dur -= TF
        frames.append((save(full), max(dur, 0.05)))
        prev = full
    if not short:
        frames.append((save(endcard(cv)), 5.0))
    lst = fdir / "list.txt"
    with open(lst, "w") as f:
        for pth, dur in frames:
            f.write(f"file '{pth}'\nduration {dur:.4f}\n")
        f.write(f"file '{frames[-1][0]}'\n")
    run(["ffmpeg", "-y", "-v", "error", "-f", "concat", "-safe", "0", "-i", str(lst), "-i", str(wav),
         "-vf", "fps=30,format=yuv420p", "-c:v", "libx264", "-preset", "veryfast", "-crf", "22",
         "-af", ("aresample=44100" if flag("FAKE_TTS") else "loudnorm=I=-16:TP=-1.5:LRA=11,aresample=44100"),
         "-c:a", "aac", "-b:a", "160k",
         "-shortest", "-movflags", "+faststart", str(out_mp4)])


# ============================================================ THUMBNAIL
GLYPHS = {"math": ["x²", "π", "√", "∑", "f(x)", "∫"], "exam": ["A B C D", "SAT", "AP", "✓"],
          "science": ["Δ", "H₂O", "DNA", "E=mc²"], "humanities": ["1776", "§", "★", "AP"]}


def make_thumb(text, area, path):
    W, H = 1280, 720
    cv = Canvas(False)
    im = cv.bg(DARK).copy()
    d = ImageDraw.Draw(im)
    for size in (130, 114, 100, 88, 76):
        fnt = font("bold", size)
        lines = wrap(text.upper(), fnt, 700)
        if len(lines) <= 3:
            break
    draw_lines(d, 70, 130, lines, fnt, WHITE, size * 1.18, hl=True)
    card = Image.new("RGBA", (440, 440), (0, 0, 0, 0))
    cd = ImageDraw.Draw(card)
    cd.rounded_rectangle([10, 10, 430, 430], radius=48, fill=YEL)
    g = random.choice(GLYPHS.get(area, GLYPHS["math"]))
    gsize = 200 if len(g) <= 3 else 110
    cd.text((220, 225), g, font=font("math", gsize), fill=NAVY, anchor="mm")
    card = card.rotate(-6, expand=True, resample=Image.BICUBIC)
    im.paste(card, (770, 140), card)
    wm = wordmark(46)
    im.paste(wm, (70, H - 110), wm)
    im.convert("RGB").save(path, "JPEG", quality=88)


# ============================================================ YOUTUBE
_TOKEN = None
_TOKEN_EXP = 0.0


def yt_token(force=False):
    """Access tokens live ~1 hour and a long video takes longer to build, so refresh whenever it is about to expire."""
    global _TOKEN, _TOKEN_EXP
    if _TOKEN and not force and time.time() < _TOKEN_EXP - 300:
        return _TOKEN
    r = requests.post("https://oauth2.googleapis.com/token", data={
        "client_id": os.environ["YT_CLIENT_ID"], "client_secret": os.environ["YT_CLIENT_SECRET"],
        "refresh_token": os.environ["YT_REFRESH_TOKEN"], "grant_type": "refresh_token"}, timeout=60)
    r.raise_for_status()
    j = r.json()
    _TOKEN = j["access_token"]
    _TOKEN_EXP = time.time() + int(j.get("expires_in", 3600))
    return _TOKEN


def fetch_comments():
    """Latest viewer comments on the channel (used to pick requested topics). Never fatal."""
    try:
        h = {"Authorization": f"Bearer {yt_token()}"}
        ch = requests.get("https://www.googleapis.com/youtube/v3/channels", params={"part": "id", "mine": "true"},
                          headers=h, timeout=30).json()["items"][0]["id"]
        r = requests.get("https://www.googleapis.com/youtube/v3/commentThreads", headers=h, timeout=30,
                         params={"part": "snippet", "allThreadsRelatedToChannelId": ch, "maxResults": 60,
                                 "order": "time", "textFormat": "plainText"}).json()
        return [it["snippet"]["topLevelComment"]["snippet"]["textDisplay"][:200] for it in r.get("items", [])]
    except Exception as e:
        log("  comments unavailable:", e)
        return []


def yt_upload(path, title, desc, tags, publish_at):
    size = Path(path).stat().st_size
    clean, total = [], 0
    for t in tags:
        t = re.sub(r"[<>#]", "", str(t)).strip()
        if t and total + len(t) + 1 < 450:
            clean.append(t)
            total += len(t) + 1
    status = {"privacyStatus": "private" if publish_at else "public", "selfDeclaredMadeForKids": False}
    if publish_at:
        status["publishAt"] = publish_at.strftime("%Y-%m-%dT%H:%M:%S.000Z")
    meta = {"snippet": {"title": title[:98], "description": desc[:4900], "tags": clean, "categoryId": "27",
                        "defaultLanguage": "en", "defaultAudioLanguage": "en"}, "status": status}
    last = None
    for attempt in range(3):
        try:
            token = yt_token(force=attempt > 0)
            init = requests.post("https://www.googleapis.com/upload/youtube/v3/videos?uploadType=resumable&part=snippet,status",
                                 headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json; charset=UTF-8",
                                          "X-Upload-Content-Type": "video/mp4", "X-Upload-Content-Length": str(size)},
                                 data=json.dumps(meta), timeout=60)
            init.raise_for_status()
            with open(path, "rb") as f:
                up = requests.put(init.headers["Location"], data=f, timeout=3600,
                                  headers={"Content-Type": "video/mp4", "Content-Length": str(size)})
            up.raise_for_status()
            return up.json()["id"]
        except Exception as e:
            last = e
            log("  upload retry:", e)
            time.sleep(10 * (attempt + 1))
    raise RuntimeError(f"upload failed: {last}")


def _why(e):
    try:
        return f"{e} | {e.response.text[:220]}"
    except Exception:
        return str(e)


def srt_from(tl):
    def ts(x):
        ms = int(round(x * 1000))
        return f"{ms // 3600000:02d}:{ms // 60000 % 60:02d}:{ms // 1000 % 60:02d},{ms % 1000:03d}"
    out = []
    for i, (a, b, txt) in enumerate(tl["cues"], 1):
        out.append(f"{i}\n{ts(a)} --> {ts(b)}\n{re.sub(r'[*]+', '', txt)}\n")
    return "\n".join(out)


def yt_captions(video_id, srt):
    """English captions (indexed by search, helps watch time). Needs the youtube.force-ssl scope; never fatal."""
    try:
        b = "highlitcaps"
        meta = json.dumps({"snippet": {"videoId": video_id, "language": "en", "name": "English", "isDraft": False}})
        body = (f"--{b}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n{meta}\r\n--{b}\r\nContent-Type: application/octet-stream\r\n\r\n").encode() \
            + srt.encode("utf-8") + f"\r\n--{b}--".encode()
        r = requests.post("https://www.googleapis.com/upload/youtube/v3/captions?uploadType=multipart&part=snippet",
                          headers={"Authorization": f"Bearer {yt_token()}", "Content-Type": f"multipart/related; boundary={b}"}, data=body, timeout=120)
        r.raise_for_status()
    except Exception as e:
        log("  captions not uploaded:", _why(e))


def yt_comment(video_id, text):
    try:
        r = requests.post("https://www.googleapis.com/youtube/v3/commentThreads", params={"part": "snippet"},
                          headers={"Authorization": f"Bearer {yt_token()}"}, timeout=60,
                          json={"snippet": {"videoId": video_id, "topLevelComment": {"snippet": {"textOriginal": text[:9000]}}}})
        r.raise_for_status()
    except Exception as e:
        log("  answer-key comment not posted (token needs the youtube.force-ssl scope):", _why(e))


def yt_playlist_add(st, video_id, title):
    """One playlist per course = students binge the whole course and YouTube can recommend it as a series. Never fatal."""
    try:
        h = {"Authorization": f"Bearer {yt_token()}"}
        pls = st.setdefault("playlists", {})
        if title not in pls:
            r = requests.get("https://www.googleapis.com/youtube/v3/playlists", headers=h, params={"part": "snippet", "mine": "true", "maxResults": 50}, timeout=30).json()
            for it in r.get("items", []):
                pls[it["snippet"]["title"]] = it["id"]
        if title not in pls:
            r = requests.post("https://www.googleapis.com/youtube/v3/playlists", headers=h, params={"part": "snippet,status"}, timeout=30,
                              json={"snippet": {"title": title, "description": f"{title}: step-by-step lessons, practice problems and exam questions by Highlit."},
                                    "status": {"privacyStatus": "public"}})
            r.raise_for_status()
            pls[title] = r.json()["id"]
        for k in range(2):
            r = requests.post("https://www.googleapis.com/youtube/v3/playlistItems", headers=h, params={"part": "snippet"}, timeout=30,
                              json={"snippet": {"playlistId": pls[title], "resourceId": {"kind": "youtube#video", "videoId": video_id}}})
            if r.status_code == 409 and k == 0:
                time.sleep(20)   # the new video may not be ready yet
                continue
            r.raise_for_status()
            break
    except Exception as e:
        log("  playlist not updated:", _why(e))


def yt_thumb(video_id, path):
    try:
        r = requests.post(f"https://www.googleapis.com/upload/youtube/v3/thumbnails/set?videoId={video_id}",
                          headers={"Authorization": f"Bearer {yt_token()}", "Content-Type": "image/jpeg"},
                          data=Path(path).read_bytes(), timeout=120)
        r.raise_for_status()
    except Exception as e:
        log("  thumbnail not set (channel may need phone verification):", e)


# ============================================================ PACKAGING
def mmss(t):
    t = int(t)
    return f"{t // 60}:{t % 60:02d}"


def build_description(script, tl, st=None):
    hs = [h if h.startswith("#") else "#" + h for h in script["hashtags"]]
    hs = [re.sub(r"\s+", "", h) for h in hs]
    last = (st or {}).get("last_long")
    if script["kind"] == "short":
        if "#Shorts" not in hs:
            hs.insert(0, "#Shorts")
        link = f"\n\nFull lesson: {last['title']}\n{last['url']}" if last else ""
        return f"{script['description']}\n\nCan you solve the challenge at the end? Comment your answer below!{link}\n\nNew lesson every day on Highlit.\n\n{' '.join(hs[:5])}"
    chapters, lastt = [], -99
    for sc, stt in zip(script["scenes"], tl["scene_starts"]):
        if stt - lastt >= 10:
            chapters.append(f"{mmss(stt)} {sc['heading']}")
            lastt = stt
    if chapters:
        chapters[0] = "0:00" + chapters[0][chapters[0].index(" "):]
    probs = script.get("problems") or {}
    key = ""
    if probs:
        pr, ex = probs["practice"], probs["exam"]
        ci = "ABCD".index(ex["correct"]) if ex.get("correct") in list("ABCD") else 0
        key = ("PRACTICE ANSWER KEY (try each one before you look!)\n"
               f"1) {pr.get('task', '')} {pr.get('statement_eq') or pr['statement']}\n   Answer: {pr['answer_text']}\n"
               f"2) {ex['statement']}\n   Answer: {ex['choices'][ci]}")
    more = f"More {script.get('course', '')} lessons:\n{last['title']}\n{last['url']}" if last else ""
    parts = [script["description"], "Chapters:\n" + "\n".join(chapters) if len(chapters) >= 3 else "", key, more,
             "Comment the topic or exam question you want us to solve next - we read every comment.",
             "Highlit: AP, SAT, ACT and high school help explained like two friends talking.", " ".join(hs[:3])]
    return "\n\n".join(p for p in parts if p)


def slot_time(now_utc, kind, wd):
    """Publish time = fixed Saudi-time slot of today (all slots are inside 10:00-15:00 KSA)."""
    if kind == "long":
        if wd not in LONG_SLOTS:
            return None
        hhmm = LONG_SLOTS[wd][1]
    else:
        hhmm = SHORT_SLOTS[wd]
    h, m = map(int, hhmm.split(":"))
    d = now_utc.astimezone(KSA)
    t = datetime(d.year, d.month, d.day, h, m, tzinfo=KSA).astimezone(timezone.utc)
    return t if t > now_utc + timedelta(minutes=15) else None


